window.LQ_SOL=window.LQ_SOL||{};window.LQ_SOL["2012年及以前"]={"1426":[{"aid":"106360","title":"bfs之八数码问题/一维化二维思路--蓝桥杯省赛2023","date":"2024-09-13","likes":1,"views":874,"md":"S 正文\n原题链接：蓝桥杯历届试题-九宫重排\n\n Server-side output Markdown text\n# 此题使用简单的宽搜解决\n###### 八数码原题链接请看[八数码原题链接](https://www.xfxcy.com/p/P0231 \"八数码原题链接\")\n\n###### 分享一下我的洛谷第一个绿题题解[bfs--Knights of Ni S](https://www.luogu.com.cn/article/2bikh8y1 \"bfs--Knights of Ni S\")\n##### 简单的bfs 只是加了一点点的 将原来的一维坐标二维化即可完美ac本题、\n\n题意是 ： 给定长度为9的字符串 并通过一些手段 将其排列为目标序列\n###### 一维的字符串在bfs中并不好操作 所以我们找到字符串中的‘.’ 根据他的位置来移动整个字符串；\n\n我们知道 在c++中的数组 通常 行为x 列为y 所以无论在什么时候 在原一维数组中将下表 /3 就可以得到二维的x坐标 同理 %3 就是列的坐标 二维化一维同理 反着来就行了，。，\n\n###### Code：\n```cpp\n#include <iostream>\n#include <cstring>\n#include <algorithm>\n#include <unordered_map>\t\t//使用map记录每次排列的字符串需要改动的次数 优点是 使用哈希表 速度很%%\n#include <queue>\n\n#define int long long  //个人习惯\n\nusing namespace std;\nstring s , en;  // s为初始状态 en为终态\n\nint dx[] = {1 , 0 , -1 , 0} , dy[] = {0 , 1 , 0 , -1}; //从四个方向搜索\n\nsigned main()\n{\n    cin >> s >> en;\n\n    unordered_map<string , int> map;  //因为本题是要对字符串处理 所以使用string作为键值；\n    queue<string> q;\n\n    q.push(s);\n\n    while (!q.empty())    //bfs开始\n    {\n        auto t = q.front();\n        q.pop();\n        int dis = map[t];\n        if (t == en)\n        {\n            cout << dis << endl;  //找到终态 直接输出并结束程序\n            return 0;\n        }\n\n        int k = t.find('.');   //此函数的作用是找到‘.’ 的位置\n        int a = k / 3 , b = k % 3; //得到二维下表\n\n        for (int i = 0 ; i < 4 ; i ++ )\n        {\n            int x = a + dx[i] , y = b + dy[i];\n            if (x >= 0 && x < 3 && y >= 0 && y < 3) //注意边界\n            {\n                swap(t[k] , t[x * 3 + y]);  //回到一维状态下标交换字符\n                if (!map.count(t)) //如果该字符串不是第一次出现 即最少操作次数加一\n                {\n                    map[t] = dis + 1;\n                    q.push(t);\n                }\n                swap(t[k] , t[x * 3 + y]);  //回溯状体 我们有4个方向需要寻找 不回溯就会 导致位置偏移\n            }\n        }\n    }\n    cout << -1 << endl;  //没有找到方案 输出-1\n    return 0;\n}\n```\n\n E 正文"},{"aid":"106358","title":"A star/A * 路径规划算法","date":"2024-09-13","likes":0,"views":805,"md":"S 正文\n原题链接：蓝桥杯历届试题-九宫重排\n\n Server-side output Markdown text\n# A star/A * 路径规划算法\n## 曼哈顿距离介绍: [详情](https://baike.baidu.com/item/%E6%9B%BC%E5%93%88%E9%A1%BF%E8%B7%9D%E7%A6%BB/743092 \"详情\")\n曼哈顿距离是种使用在几何度量空间的几何学用语，用以标明两个点在标准坐标系上的绝对轴距总和。****也就是红线代表曼哈顿距离****\n![](/image_editor_upload/20240913/20240913062935_36951.png)\n# AC代码\n```cpp\n#include<bits/stdc++.h>\n#define ULL unsigned long long\n#define LL long long\n#define PII pair<int,int>\nusing namespace std;\nconst int N = 1e6 + 10,M = 2 * 1e4 + 10,inf = 0x3f3f3f3f;\n\ntypedef pair<int,string> PIS;\n\nstring endd,start;\nunordered_map<string,int> dist; //记录状态和所用步数\nint dir[4][2] = {{-1,0},{0,1},{1,0},{0,-1}}; //方向数组\nint f(string str)\n//估价函数-用于计算所有点到终点对应位置的曼哈顿距离之和\n{\n    int res = 0;\n    for(int i=0;i<str.size();i++)\n    {\n        if(str[i]!='.')\n        {\n            int t = str[i] - '1';\n            res += (abs(i/3 - t/3) + abs(i%3 - t%3));\n            //计算所有曼哈顿距离之和\n        }\n    }\n    return res;\n}\nbool bfs(string start,string end)\n{\n\tif(start == end) return true; //起点就是终点就返回true\n\n    priority_queue<PIS,vector<PIS>,greater<PIS>> heap;\n    //按所有状态的曼哈顿距离之和放入优先队列(优先拿距离最小的状态)\n    heap.push({f(start),start});\n    dist[start] = 0;\n    while (heap.size())\n    {\n        auto t = heap.top();\n        heap.pop();\n        string state = t.second;\n        int x,y;\n        for(int i=0;i<state.size();i++)\n        {\n            if(state[i]=='.')\n            {\n                x = i / 3;\n                y = i % 3;\n                // 找到空位的一维坐标转化为二维坐标\n            }\n        }\n        string soure = state; //存储字符串,后面有用\n        for(int i=0;i<4;i++)\n        {\n            int a = x + dir[i][0] , b = y + dir[i][1];\n            if(a < 0 || b < 0 || a >= 3 || b >= 3) continue;\n            state = soure; //复原state，循环可能会导致state变化\n            swap(state[a*3 + b],state[x*3 + y]);\n\t\t\t//二维转化回一维\n            if(dist.count(state)==0 || dist[state] > dist[soure] + 1)\n            {\n                // 如果达到这个状态所需步数更小，则需要优化这个步数\n                dist[state] = dist[soure] + 1;\n                if(state == end) return true;\n\t\t\t\t// 达到目标状态退出函数返回true\n                heap.push({f(state) + dist[state],state});\n                //加入当前步数+估价函数值的和\n            }\n        }\n    }\n\t//未找到返回false\n\treturn false;\n}\nint main()\n{\n    ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);\n    cin>>start>>endd;\n\n\tif(bfs(start,endd))\n    cout<<dist[endd]<<endl; //输出最终状态的步数\n\telse cout<<\"-1\"<<endl;\n\n    return 0;\n}\n\n```\n\n E 正文"},{"aid":"95381","title":"BFS+康托压缩","date":"2023-03-29","likes":0,"views":795,"md":"S 正文\n原题链接：蓝桥杯历届试题-九宫重排\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include\nusing namespace std;\nstring s1,s2;\nint a[5][5],b[5][5];\nint jiecheng[10]={1,1,2,6,24,120,720,5040,40320,362880};\nbool vis[363000];\nint cod[10];\nint nixvnum[10];\nint x,y;//空格所在的坐标\nint endjvmian;\nint mov[4][2]={{-1,0},{1,0},{0,-1},{0,1}};\nstruct sit{\n\tint a[5][5];\n\tint x;\n\tint y;\n\tint step;\n};\nvoid debug(sit sit1){\n\tcout<<\"x=\"<<sit1.x<<\"y=\"<<sit1.y<<\"step=\"<<sit1.step<<endl;\n\tfor(int i=1;i<=3;i++){\n\t\tfor(int j=1;j<=3;j++){\n\t\t\tcout<<sit1.a[i][j];\n\t\t}\n\t\tcout<<endl;\n\t}\n\tcout<<endl;\n}\nint Cantor(int tu[5][5]){\n\tfor(int i=1;i<=3;i++){\n\t\tfor(int j=1;j<=3;j++){\n\t\t\tcod[(i-1)*3+j]=tu[i][j];\n\t\t}\n\t}\n\tmemset(nixvnum,0,sizeof(nixvnum));\n\tfor(int i=1;i<=8;i++){\n\t\tfor(int j=i+1;j<=9;j++){\n\t\t\tif(cod[i]>cod[j])nixvnum[i]++;\n\t\t}\n\t}\n\tint ret=0;\n\tfor(int i=1;i<=8;i++){\n\t\tret+=nixvnum[i]*jiecheng[9-i];\n\t}\n\treturn ret;\n}\nvoid init(){\n\tfor(int i=1;i<=3;i++){\n\t\tfor(int j=1;j<=3;j++){\n\t\t\tif(s1[(i-1)*3+j-1]=='.'){\n\t\t\t\tx=i;y=j;\n\t\t\t\ta[i][j]=9;\n\t\t\t}\n\t\t\telse a[i][j]=s1[(i-1)*3+j-1]-'0';\n\t\t}\n\t}\n\tfor(int i=1;i<=3;i++){\n\t\tfor(int j=1;j<=3;j++){\n\t\t\tif(s2[(i-1)*3+j-1]=='.'){\n\t\t\t\tb[i][j]=9;\n\t\t\t}\n\t\t\telse b[i][j]=s2[(i-1)*3+j-1]-'0';\n\t\t}\n\t}\n\tendjvmian=Cantor(b);\n}\nint bfs(){\n\tqueue\n\tsit now,nex;\n\tint jvmian;\n\tfor(int i=1;i<=3;i++){\n\t\tfor(int j=1;j<=3;j++){\n\t\t\tnow.a[i][j]=a[i][j];\n\t\t}\n\t}\n\tnow.x=x;now.y=y;now.step=0;\n\tjvmian=Cantor(now.a);\n\tif(jvmian==endjvmian)return 0;\n\tvis[jvmian]=1;\n\tq.push(now);\n\twhile(!q.empty()){\n\t\tnow=q.front();q.pop();\n\t\t//debug(now);\n\t\tjvmian=Cantor(now.a);\n\t\tfor(int i=0;i<4;i++){\n\t\t\tint x=now.x,y=now.y;\n\t\t\tint x1=x+mov[i][0],y1=y+mov[i][1];\n\t\t\tif(!(1<=x1&&x1<=3&&1<=y1&&y1<=3))continue;\n\t\t\tswap(now.a[x][y],now.a[x1][y1]);\n\t\t\tjvmian=Cantor(now.a);\n\t\t\tswap(now.a[x][y],now.a[x1][y1]);\n\t\t\tif(jvmian==endjvmian)return now.step+1;//已经到达终点\n\t\t\tif(vis[jvmian])continue;//这种局面已经访问过了\n\t\t\tnex.x=x1;nex.y=y1;\n\t\t\tnex.step=now.step+1;\n\t\t\tmemcpy(nex.a,now.a,sizeof(a));\n\t\t\tswap(nex.a[x][y],nex.a[x1][y1]);\n\t\t\tvis[jvmian]=1;\n\t\t\tq.push(nex);\n\t\t}\n\t}\n\treturn -1;\n}\nint main(){\n\tios::sync_with_stdio(false);\n\t//debug();\n\tcin>>s1;\n\tcin>>s2;\n\tinit();\n\tcout<<bfs();\n}\n\n E 正文"},{"aid":"91452","title":"适合初学者看通俗易懂C++","date":"2022-11-12","likes":0,"views":1028,"md":"S 正文\n原题链接：蓝桥杯历届试题-九宫重排\n\n解题思路:\n        1.题目要求最小步数，利用BFS搜索，一旦找到就是最小步数；\n        2.使用双向搜索减少时间，分别从初态和终态使用BFS，使用map关联数组命名为maps的键记录变化过程中每一种字符串状态，其中，从初态开始变化的键对应的值都计为1，从终态开始变化的键对应的值都计为2\n        3.当从初态和终态变化得到的状态一样时，代表可以从初态变化到终态，获得最小步数；若从初态和从终态得到的所有状态都没有一样的时，代表无论多少步都不可到达，输出结果-1\n        4.利用map关联数组命名为steps记录从出态和终态移动了多少步数，当从初态和终态移动得到一样状态时，即maps的值相加等于3时，将从出态移动的步数和从终态移动的步数相加得到结果。\n        5.这里用字符串表示表格状态，对于如何找到“.”以及如何让空白与数字交换，利用如下方法：\n                以题目初态为例，将12345678.赋值给string initial，那么得到字符串的中字符位置用i*3+j表示\nint t;\nint x, y;\nfor(int i = 0; i<3; i++){\n    for(int j = 0; j<3; j++){\n\tt = i*3+j;\n\tif(initial[t] == '.'){\n\t    x = i;\n\t    y = j;\n\t    break;\n\t\t\t}\n\t}\n}\nt = x*3+y;            设置横纵坐标x,y，若表格中数字想向上移动一个位置，即列不变，行减一，那么移动后finalx=x-1;finaly=y;数字想向左移动一个位置，即行不变，列减一，那么移动后finalx=x;finaly=y-1;找到finalx,finaly后，将变化前initial字符串中finalx*3+finaly位置对应的值赋给变化后final字符串x*3+y位置，后者同理，这样就完成了数字在表格中的移动，并且获得了从初态到下一状态的变化，注意final代表的是变化后的状态，initial代表的是变化前的状态，不应当是初态，也可以是终态，或者变化过程中任一状态;\n\n注意fianlx,finay均要满足>=0且<3\nstring final = initial;\n\tfinal[t] = initial[finalx*3+finaly];\n\tfinal[nx*3+ny] = initial[t];        6.步数共有三种情况:(1)输入时初态和终态就相同，步数直接输出0；\n                                       (2)初态终态初始时不相同，但是可以通过转化得到，计算步数输出;\n\n                                       (3)初态和终态初始时不同，但是无法通过转换得到，输出-1\n\n知识了解：\nqueue:只能访问 queue<T> 容器适配器的第一个和最后一个元素。只能在容器的末尾添加新元素，只能从头部移除元素。\nfront()：返回 queue 中第一个元素的引用。如果 queue 是常量，就返回一个常引用；如果 queue 为空，返回值是未定义的。\npush(T&& obj)：以移动的方式在 queue 的尾部添加元素。这是通过调用底层容器的具有右值引用参数的成员函数 push_back() 来完成的。\npop()：删除 queue 中的第一个元素。\nempty()：如果 queue 中没有元素的话，返回 true。\n\n2.map<string, int> T 是一个声明，用于生成关联数组，该关联数组管理以string为键的int元素。初始int默认为0;\n参考代码:\n#include<iostream>\n#include<map>\n#include<queue>\n#include<string>\nusing namespace std;\n// 定义要用到的变量\n// 位移\nint yd[4][2]={1,0,-1,0,0,1,0,-1};\n// 表格状态，由初态还是终态转变来\nmap<string,int> maps;\n// 当前状态是第几步\nmap<string,int> steps;\n// 输入字符串\nstring a,b;\n// 双向bfs\nint bfs(){\n    // 若输入a,b相等,步数为零\n    if(a==b){\n        return 0;\n    }\n    queue<string> que;\n    que.push(a);\n    que.push(b);\n    // 可以通过转化得到，计算步数\n    while(!que.empty()){\n        // 获取一个状态之后弹出它，若一直找不到相同状态就会把pue删除空，跳出循环\n        string initial=que.front();\n        que.pop();\n\n        // 创建状态索引\n        int t;\n        // 创建坐标\n        int x,y;\n        // 找到空白，即“.”\n        for(int i=0;i<3;i++){\n            for(int j=0;j<3;j++){\n                t=i*3+j;\n                if(initial[t]=='.'){\n                    x=i;\n                    y=j;\n                    break;\n                }\n            }\n        }\n        t=x*3+y;\n        // 实现四种空白的位移，注意找到后的坐标要满足大于等于0且小于3才可进行空白的移动\n        for(int i=0;i<4;i++){\n            // 变换后x坐标\n            int finalx=x+yd[i][0];\n            int finaly=y+yd[i][1];\n            // 转换后坐标是否满足条件,否则会超出表格\n            if(finalx>=0&&finalx<3&&finaly>=0&&finaly<3){\n                string final=initial;\n                // 实现空白和目标位置交换，得到转化后状态\n                final[t]=initial[finalx*3+finaly];\n                final[finalx*3+finaly]=initial[t];\n                // 如果maps里面这个键的值为0，代表这个状态第一次出现\n                if(!maps[final]){\n                    // 将转化前状态的maps值给现在状态的，表示现在状态由初态还是终态方向转化来的\n                    maps[final]=maps[initial];\n                    // 代表现在是该方向转化的第几步\n                    steps[final]=steps[initial]+1;\n                    /* 将该方向目前状态放入que，que循环里初态方向和终态方向交替循环,\n                    每次进入都是该方向最新状态*/\n                    que.push(final);\n                }\n                /* 如果交换后获得的状态已经存在，那么该状态已经改过键值，若与当前转换前状态键值\n                相加为3，则代表来两个状态来自方向不一样但可以找到相同状态，即可找到最小步数。\n                */\n                else if(maps[final]+maps[initial]==3){\n                    // 另一方向步数+当前方向转换前状态步数+现在这一步\n                    return steps[final]+steps[initial]+1;\n                }\n\n            }\n        }\n    }\n    return -1;\n}\nint main()\n{\n    cin>>a>>b;\n    // 由初态a转化来的maps值为1，由终态b转化来的maps值为2\n    maps[a]=1;\n    maps[b]=2;\n    cout<<bfs()<<endl;\n    return 0;\n}\n\n E 正文"},{"aid":"85830","title":"九宫重排【Python】【BFS+降维+hash判重】","date":"2022-03-27","likes":0,"views":1313,"md":"S 正文\n原题链接：蓝桥杯历届试题-九宫重排\n\n Server-side output Markdown text\n```python\nfrom collections import deque\nfrom typing import List\ndirect = [3, -3, -1, 1]\ndef check(now,target):\n    # 边界判断，把 0～8 看作 3*3 ，则不能从边界跨越下一个边界\n    if((now==2 and target==3) or (now==3 and target==2)): return False\n    if((now==5 and target==6) or (now==6 and target==5)): return False\n    if(target<0 or target>8): return False\n    return True\ndef operate(now,target,status: List[str]):\n    # 复制之后交换元素\n    this = status.copy()\n    this[now],this[target] = this[target],this[now]\n    return this\ndef bfs(start):\n    q = deque()\n    q.append([start, 0, origin])\n    while(len(q) != 0):\n        now, step, status = q.popleft()\n        if(status == end):  return step\n        for d in direct:\n            target = now + d\n            if(check(now,target)):\n                new_status = operate(now,target,status)\n                status_hash = ''.join(new_status)\n                if(status_hash in inq): continue # 判重\n                inq[status_hash] = True\n                q.append([target,step+1,new_status])\n\norigin = list(input())\nend = list(input())\ninq  = {}\nstart = origin.index('.')\nstep = bfs(start)\nprint(step)\n```\n\n E 正文"}],"1434":[{"aid":"110202","title":"蓝桥杯2012以前历届试题-回文数字","date":"2026-03-02","likes":1,"views":412,"md":"S 正文\n原题链接：蓝桥杯历届试题-回文数字\n\n解题思路:12321。这个数本来是从左往右的，将这个数通过取余从右往左拼成新数，一样就是回文数。\n例：1335321 拼成了 1235331\n如果 1335331 拼成 1335331\n\n注意事项:\n\n参考代码:\n#include<iostream>\nusing namespace std;\nint main()\n{\n    int n;int f=0;\n    cin>>n;\n    for(int i=10000;i<1000001;i++)\n    {\n        int i1=i,x=0;\n        int sum=0;\n        while(i1)\n        {\n            x=x*10+i1%10;\n            sum+=i1%10;\n            i1/=10;\n        }\n        if(x==i&&sum==n)\n        {cout<<i<<endl;f=1;}\n    }\n    if(f==0) cout<<-1;\n    return 0;\n}\n\n E 正文"},{"aid":"108994","title":"回文数字-将数字转换为字符串进行比较","date":"2025-04-06","likes":0,"views":583,"md":"S 正文\n原题链接：蓝桥杯历届试题-回文数字\n\n解题思路:\n\n注意事项:\n\n参考代码:\n\n#include <iostream>\n#include <string>\n#include <cmath>\nusing namespace std;\n\n// 判断数字是否是回文数\nbool isPalindrome(int num) {\n    string s = to_string(num);\n    int len = s.length();\n    for (int i = 0; i < len / 2; ++i) {\n        if (s[i] != s[len - 1 - i]) {\n            return false;\n        }\n    }\n    return true;\n}\n\n// 计算数字的各个数位之和\nint digitSum(int num) {\n    int sum = 0;\n    while (num > 0) {\n        sum += num % 10;\n        num /= 10;\n    }\n    return sum;\n}\n\nint main() {\n    int n;\n    cin >> n; // 输入要求的数位和\n\n    bool found = false;\n\n    // 检查5位数的回文数\n    for (int i = 10000; i <= 99999; ++i) {\n        if (isPalindrome(i) && digitSum(i) == n) {\n            cout << i << endl;\n            found = true;\n        }\n    }\n\n    // 检查6位数的回文数\n    for (int i = 100000; i <= 999999; ++i) {\n        if (isPalindrome(i) && digitSum(i) == n) {\n            cout << i << endl;\n            found = true;\n        }\n    }\n\n    // 如果没有找到符合条件的回文数\n    if (!found) {\n        cout << -1 << endl;\n    }\n\n    return 0;\n}\n\n E 正文"},{"aid":"108758","title":": 蓝桥杯历届试题-回文数字","date":"2025-03-10","likes":1,"views":756,"md":"S 正文\n原题链接：蓝桥杯历届试题-回文数字\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include<iostream>\n#include<set>\nusing namespace std;\nint main()\n{\n\tint n;\n\tset<int>s;\n\tcin >> n;\n\tfor (int i = 10000; i < 100000; i++)\n\t{\n\t\tif (i % 10 + (i / 10 % 10) + (i / 100 % 10) + (i / 1000 % 10) + (i / 10000) == n&& i % 10== (i / 10000)&& (i / 10 % 10)== (i / 1000 % 10))\n\t\t{\n\t\t\ts.insert(i);\n\t\t}\n\t}\n\tfor (int i = 100000; i < 1000000; i++)\n\t{\n\t\tif (i % 10 + (i / 10 % 10) + (i / 100 % 10) + (i / 1000 % 10) + (i / 10000%10)+(i/100000) == n && i % 10 == (i / 100000) && (i / 10 % 10) == (i / 10000 % 10)&& (i / 100 % 10)== (i / 1000 % 10))\n\t\t{\n\t\t\ts.insert(i);\n\t\t}\n\t}\n\tif (s.empty())\n\t\tcout << \"-1\" << endl;\n\tfor (auto p = s.begin(); p != s.end(); p++)\n\t\tcout << *p << endl;\n}\n\n E 正文"},{"aid":"108547","title":"题解 1434: 蓝桥杯历届试题-回文数字（最简单易懂）","date":"2025-02-23","likes":5,"views":1007,"md":"S 正文\n原题链接：蓝桥杯历届试题-回文数字\n\n解题思路：将数字转换为字符串，顺序和逆序遍历字符串的每一位判断是否相等，若每一位都相等则为回文数。并使用found标记有没有找到满足条件的数字\n\n参考代码：\nx = int(input())\nfound = False\nfor i in range(10000,1000001):\n    i = str(i)\n    count = 0\n    for j in range(len(i)):\n        count += int(i[j])\n    if i[0:] == i[::-1] and count == x:\n        print(i)\n        found = True\nif found == False : print('-1')\n\n E 正文"},{"aid":"107145","title":"一直83直到我把输出-1的语句放在外面","date":"2024-11-14","likes":1,"views":688,"md":"S 正文\n原题链接：蓝桥杯历届试题-回文数字\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include<iostream>\nusing namespace std;\nint main()\n{\n \tint n,count=0;\n\tcin>>n;\n\tfor(int i=10000;i<1000000;i++)\n\t{\n\t\tint b=i,m=0,sum=0;\n\t\twhile(b>0)\n\t\t{\n\t\tm=m*10+b%10;\n\t\tsum=sum+b%10;\n\t\tb=b/10;\n\t\t}\n\t\tif(m==i&&sum==n)\n\t\t{\n\t\t    count++;\n\t\t\tcout<<i<<endl;\n\t\t}\n\t}\n\tif(count==0)\n\t   {\n\t       cout<<-1<<endl;\n\t    }\n}\n\n E 正文"}],"1435":[{"aid":"102557","title":"1435: 蓝桥杯历届试题-国王的烦恼","date":"2024-02-06","likes":0,"views":888,"md":"S 正文\n原题链接：蓝桥杯历届试题-国王的烦恼\n\n Server-side output Markdown text\n# 1435: 蓝桥杯历届试题-国王的烦恼\n## 抽象题意\n按照题目含义，在某一天内只要发生两个小岛是不可相互抵达的就会发生抗议。还需要注意在同一天发生的抗议仅计算一次。考虑到我们要求解的是抗议次数。不妨先记抗议次数为 answer 。综上描述，触发 answer += 1 的条件是**某一天内存在两个小岛不可相互抵达**。\n接下来，继续抽象条件。注意到题目是的逻辑数据结构一定是图，因此考虑抽象为图论问题，或者基于图论可以解决。至此转义语义，能后相互抵达等价于图论中能否连通，桥等价于图论中的边。换言之，目前构成的图我们可以暂且称之为连通图。暂且的理由稍后再说。\n如果采用检测的方式来检测连通图是否被破环是不好的，无法通过所有数据。所以要考虑如何转义条件。现在考虑连通图的破坏会带来的后果，最好是数值上的呈现。很快会发现，如果因为某一条桥的破环发生了连通图的结构被破环 --> 数值上，连通图的数量一定会增加,其次这条桥 (边) 就是当前图下的割。于是现在我们有两个角度：**1、求连通图的块数变化；2、求割然后比对**。\n分析之后，会发现求割的方式还是不行。因为图的数量有 t 决定，而求解割需要线性的时间。这样子的代价依旧昂贵。**换言之，从题意思路的正面 -- 破环桥 (边) 的思路代价都是巨大的**。\n那么考虑反面恢复边的情况，记录连通块的变化。注意因为是反面，所以此时连通图数量会减少而不是增加。此时，我们仍然需要考虑一条边能够连接两个连通图使得连通图个数减少。而能够帮助我们快速实现是否两个点连通的数据结构有并查集。因此考虑并查集来帮助我们实现这个判断的过程。并查集的速度很快 (可以说是接触的大部分数据结构以外最快的，一般认为是$$\\alpha(n)$$)，不需要担心判别的超时。至此我们分析出了解题的可能性。\n\n## 代码实现\n首先定义出我们的数据结构 -- 边集数组，为了可读性在这道题我们将 bridge[] 替代 edge[]。抽象层面任然是 Edge。设计一点复制用的函数。\n```cpp\n#define MAX_M 100005\nstruct Edge {\n  int from, to, time;\n\n  /* funtion member -- this code for c plus plus\n     if you are coding by c, please write this code\n\t which following independently\n  */\n  Edge() {}; // default construct function\n  Edge(int from, int to, int time) : from(from), to(to), time(time){};\n\n  inline void modify(const int data_from, const int data_to, const int data_time) {\n\tfrom = data_from;\n\tto = data_to;\n\ttime = data_time;\n  };\n\n  /*  there is a trick for sort function */\n  bool operator< (const Edge& other) const {\n\treturn time > other.time;\n  };\n}bridge[MAX_M];\n```\n按照模板设计一下并查集即可，完整代码如下。这里面设计了加速版的代码 -- 目的是躲避多余的检查。\n```cpp\n#include<iostream>\n#include<vector>\n#include<queue>\n#include<cstring>\n#include<algorithm>\n#include <iomanip>\n#include <unordered_map>\n#include <time.h>\n\n#define MAX_N 10005\n#define MAX_M 100005\n#define MAX_T 100005\nstruct Edge {\n  int from, to, time;\n\n  /* funtion member -- this code for c plus plus\n     if you are coding by c, please write this code\n\t which following independently\n  */\n  Edge() {}; // default construct function\n  Edge(int from, int to, int time) : from(from), to(to), time(time){};\n\n  inline void modify(const int data_from, const int data_to, const int data_time) {\n\tfrom = data_from;\n\tto = data_to;\n\ttime = data_time;\n  };\n\n  /*  there is a trick for sort function */\n  bool operator< (const Edge& other) const {\n\treturn time > other.time;\n  };\n}bridge[MAX_M];\n\n/*  for quick_set  */\nint quick_set[MAX_N], rank[MAX_N];\n\ninline void initilization(int n) {\n  for (int i = 1; i <= n; ++i)\n\tquick_set[i] = i;\n}\n\nint findRoot(int x) {\n  while (x != quick_set[x]) {\n\tquick_set[x] = quick_set[quick_set[x]];\n\tx = quick_set[x];\n  }\n  return x;\n}\n\n#define quicklyCheckInSameSet(root_x, root_y) ( (root_x) == (root_y) ? true : false )\ninline void quicklyUnionSet(int root_x, int root_y) {\n  if (bool flag = quicklyCheckInSameSet(root_x, root_y)) return;\n\n  if (rank[root_x] < rank[root_y])\n\tquick_set[root_x] = root_y;\n  else\n\tquick_set[root_y] = root_x;\n\n  if (rank[root_x] == rank[root_y])\n\t++rank[root_x];\n}\n\ninline void uninSet(int x, int y) {\n  int root_x = findRoot(x), root_y = findRoot(y);\n  quicklyUnionSet(root_x, root_y);\n}\n\nbool inSameSet(int x, int y) {\n  int root_x = findRoot(x), root_y = findRoot(y);\n  if (root_x == root_y) return true;\n  return false;\n}\n\nint n, m;\nint main() {\n  scanf(\"%d%d\", &n, &m);\n  /*  input the edge  */\n  {\n    int a, b, t; // avoid repeat allocate local value.\n    for (int i = 0; i < m; ++i) {\n      scanf(\"%d%d%d\", &a, &b, &t);\n\t  bridge[i].modify(a, b, t); // bridge[i] = { a, b, t };\n\t}\n  }\n\n  initilization(n);\n  std::sort(bridge, bridge + m);\n#define MAX_INT 0x3f3f3f3f\n  int ans = 0, last_day = MAX_INT;\n  bool if_not_in_same_set = 0;\n  for (int i = 0; i < m; ++i) {\n\tint from = bridge[i].from, to = bridge[i].to, time = bridge[i].time;\n\tfrom = findRoot(from), to = findRoot(to);\n\tif_not_in_same_set = !quicklyCheckInSameSet(from, to);\n\tif (if_not_in_same_set && last_day > time) {\n\t  ++ans;\n\t  last_day = time;\n\t}\n    quicklyUnionSet(from, to);\n  }\n\n\t/*  output th\n\n（正文过长，已截断，全文见原文链接）"},{"aid":"87081","title":"蓝桥杯历届试题-国王的烦恼","date":"2022-05-05","likes":0,"views":759,"md":"S 正文\n原题链接：蓝桥杯历届试题-国王的烦恼\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include<bits/stdc++.h>\nusing namespace std;\n\nconst int Max_N = 1e4+10;\nconst int Max_M = 1e5+10;\n\nstruct Brige\n{\n    int u,v;\n    int day;\n    Brige(){}\n    Brige(int u_,int v_,int day_)\n    {\n        u = u_; v = v_; day = day_;\n    }\n}brige[Max_M];\n\nint n,m;\nint cur_day;\nint par[Max_N];\nint height[Max_N];\nvoid init(int n);\nint find(int x);\nvoid unite(int x, int y);\nbool same(int x, int y);\nvoid solve();\nbool cmp(const Brige &b1, const Brige &b2);\n\nint main()\n{\n    scanf(\"%d%d\",&n,&m);\n    for( int i=0; i<m; i++ )\n    {\n        scanf(\"%d%d%d\",&brige[i].u,&brige[i].v,&brige[i].day);\n        cur_day = max( cur_day, brige[i].day);\n    }\n\n    solve();\n\n    return 0;\n}\n\nvoid init(int n)\n{\n    for( int i=1; i<=n; i++ )\n    {\n        par[i] = i;\n        height[i] = 0;\n    }\n}\n\nint find( int x )\n{\n    return x==par[x] ? x : par[x] = find(par[x]);\n}\n\nvoid unite(int x, int y)\n{\n    x = find(x); y = find(y);\n    if( x==y )\n        return;\n    if( height[x]<height[y] )\n    {\n        par[x] = y;\n    }\n    else\n    {\n        par[y] = x;\n        if( height[x]==height[y] )    height[x]++;\n    }\n}\n\nbool same(int x, int y)\n{\n    return find(x)==find(y);\n}\n\nbool cmp(const Brige &b1, const Brige &b2)\n{\n    return b1.day>b2.day;// 用>=作为条件会出错,原因是?\n}\n\nvoid solve()\n{\n    init(n);\n    sort(brige,brige+m,cmp);\n\n    int i = 0, ans = 0;\n    bool flag;\n    while( cur_day>0 && i<m )\n    {\n        flag = false;\n        for( ; i<m; i++ )\n        {\n            if( cur_day != brige[i].day )\n            {\n                cur_day = brige[i].day;\n                break;\n            }\n            int u = brige[i].u, v = brige[i].v;\n            bool temp = same(u,v);\n            unite(u,v);\n            if( flag )    continue;\n            if( temp^same(u,v) )\n            {\n                ans++;  flag = true;\n            }\n        }\n    }\n    printf(\"%d\\n\",ans);\n}\n\n E 正文"},{"aid":"80267","title":"国王的烦恼(并查集)--kruskal算法实现最小生成树(JAVA)","date":"2021-10-07","likes":0,"views":1013,"md":"S 正文\n原题链接：蓝桥杯历届试题-国王的烦恼\n\n Server-side output Markdown text\n###解题思路:\n①首先我们来了解一下什么是最小生成树:\n**假设图包含有V个顶点和E条无向(也就是双向)有权边,最少需要 V-1 条边才能连通所有顶点,这 V-1 条边和 V 个顶点构成的树,称为生成树**;像图dfs和bfs遍历都会有相应的生成树;**如果某棵树包含的 V-1 条边的权重和最小,那么对应的这颗生成树就位最小生成树**\n②怎样生成最小生成树呢?:\n两种比较经典的算法:Kruskal算法和Prim算法([配合视频和以下文字](https://www.bilibili.com/video/BV1Eb41177d1 \"配合视频和以下文字\"))。它们都用到贪心算法思想,Kruskal算法较为简单,它需要用到[并查集(如果你还不会的话,请先了解)](https://www.bilibili.com/video/BV1jv411a7LK?from=search&seid=6941188642067466287&spm_id_from=333.337.0.0 \"并查集(如果你还不会的话,请先了解)\"),我们将用它来实现最小生成树.\n初始时,每个顶点对应一个集合.按照权重从小到大依次考察每条边.如果某条边对应的两个顶点不在同一个集合中,那么我们就将这条边选入最小生成树中,并将两个对应的集合合并。如果某条边对应的两个顶点在同一个集合中,也就是两个顶点是连通的,若再添加这条边就会形成环了,故我们选择不放入最小生成树中。依次类推,直到最小生成树中包含V-1条边为止。\n上述处理思路对应代码:\n```java\nimport java.util.ArrayList;\nimport java.util.Collections;\nimport java.util.List;\n\npublic class Graph {\n    private int v;//节点的个数\n    private int e;//边的个数\n\n    private List<Edge> edges = new ArrayList<>();\n    private List<Edge> mst = new ArrayList<>();\n\n    public void kruskal(){\n       UnionFindSet unionFindSet = new UnionFindSet();\n       //从小到大排序\n\n       Collections.sort(edges);\n        for (int i = 0; i < e; i++) {\n            if(mst.size()==v-i){\n                break;\n            }\n            Edge edge = edges.get(i);\n            //边的两个点是否在同一个集合中\n            if(!unionFindSet.isSameR(edge.ui,edge.vi)){\n                mst.add(edge);\n                unionFindSet.union(edge.ui, edge.vi);\n            }\n        }\n    }\n    public class Edge implements Comparable<Edge> {\n        public int ui;\n        public int vi;\n        public int weight;\n\n        @Override\n        public int compareTo(Edge o) {\n            return o.weight - this.weight;//按权重从小到大排序\n        }\n    }\n}\n//并查集模板\nclass UnionFindSet {\n    private int p[];\n    private int rank[];\n\n    public void unionFindSet(int n) {\n        p = new int[n];\n        rank = new int[n];\n        for (int i = 0; i < n; i++) {\n            p[i] = i;\n            rank[i] = 1;\n        }\n    }\n    public void union(int i,int j){\n        i = findR(i);\n        j = findR(j);\n        if(rank[i]<rank[j]){\n            p[i]=j;\n        }else if(rank[i]>rank[j]){\n            p[j] =i;\n        }else{\n            p[i]=j;\n            rank[j]++;\n        }\n    }\n    public boolean isSameR(int i,int j){\n        return findR(i)==findR(j);\n    }\n    public int findR(int x) {\n        if (p[x] == x) return x;\n        p[x] = findR(p[x]);\n        return -1;\n    }\n}\n```\n③回到该题\n无非就是将桥的使用天数看作权重,只不过相当于天数越多权重越小(才是关键桥,没它就会抗议)\n###注意事项:\n同一天断两座桥,居民也只会抗议一天\n\n### 代码实现\n**这里代码在C语言网码上去有些显示不了,我就放图片了,正好自己码一遍增加印象吧~~~**\n![](https://i.loli.net/2021/10/07/qTMr9lHpxAimf8h.png)\n\n E 正文"},{"aid":"78380","title":"暴力想法，求大佬实现！！！","date":"2021-04-08","likes":0,"views":1484,"md":"S 正文\n原题链接：蓝桥杯历届试题-国王的烦恼\n\n//大概意思就是：构成一个较大的二位数组（！！！！这个好像不可以直接定义，需要其他办法），然后行和列就是表示两岸，数值表示之前的桥的耐久度，\n//先遍历行，如果一整行的值都是0，说明这一个岸被孤立了，所以就满足题意。跳出循环，输出day。\n#include<stdio.h>\n#include<malloc.h>\nint shuzu[10001][10001] = { 0 };//这里有点问题，数组定义过大。应该是唯一不对的点，但是在我的编译器VS2019可以用\n//数组用来存相连的情况，数组中的值存天数。\nint main()\n{\nint n = 0, m = 0, a = 0, b = 0, t = 0;\nint count = 0, day = 0;\nif (scanf(\"%d %d\", &n, &m))//输入岸和桥的值\n{\n}\nfor (int i = 1; i <= m; i++)\n{\nif (scanf(\"%d %d %d\", &a, &b, &t))//输入连接情况\n{\n}\nshuzu[a][b]= t;//把使用天数写到数组中\nshuzu[b][a] = t;\n}\nint flag = 0;//定义一个标志，用于结束循环\nwhile (flag==0)\n{\nfor (int j = 1;j <= m;j++)//先循环行\n{\nflag = 0;//先让标志归零\nfor (int k = 1; k <= m; k++)//循环列\n{\nif (shuzu[j][k]== 0)//意思就是两岸不相连\n{\ncount++;\n}\n}\nif (count == m)//说明改行所有数均为0，即这个岸不和其他岸相连，符合题意，跳出两层循环，输出day就可以了。\n{\nflag = 1;\nbreak;\n}\nelse\n{\ncount = 0;//继续循环下一行，先把count清零。\n}\n}\nif (count==m)//这里防止day++多执行；\n{\nbreak;//跳出大循环\n}\nelse\n{\nday++;//如果不满足上述条件，就说明没有岸被孤立，day++\n}\nfor (int s = 1; s <= m; s++)//判断数组中的数值，如果有大于0的，就说明还没有坏掉，让他-1，就是耐久度-1；\n{\nfor (int t = 1;t <= m;t++)\n{\nif (shuzu[s][t] > 0)\n{\nshuzu[s][t]--;\n}\n}\n}\n}\nprintf(\"%d\", day);//输出day！就是结果了。\nreturn 0;\n}\n\n E 正文"},{"aid":"78360","title":"逆向思维+并查集+一个问题?","date":"2021-04-08","likes":0,"views":1063,"md":"S 正文\n原题链接：蓝桥杯历届试题-国王的烦恼\n\n解题思路:\n    逆向思维+并查集\n注意事项:\n    sort的自定义函数如果判断条件为>=会出错，对sort不了解所以不知道原因是什么?\n参考代码:\n/*\n *国王的烦恼:逆向思维\n *\t抗议条件:前一天可以到达,而后一天不能,即联通性发生改变\n *\t如果直接用并查集会发现没有删除两点联通的函数\n *\t实际上条件的关键是联通性的改变,可以逆向思考:天数逆向,那么\n *状态的改变实际上就是前一天联通而后一天不连通,而建造的那一天即\n *是原题桥不能使用的那一天\n */\n\n#include<cstdio>\n#include<algorithm>\nusing namespace std;\n\nconst int Max_N = 1e4+10;\nconst int Max_M = 1e5+10;\n\nstruct Brige\n{\n\tint u,v;\n\tint day;\n\tBrige(){}\n\tBrige(int u_,int v_,int day_)\n\t{\n\t\tu = u_; v = v_; day = day_;\n\t}\n}brige[Max_M];\n\nint n,m;\nint cur_day;\nint par[Max_N];\nint height[Max_N];\nvoid init(int n);\nint find(int x);\nvoid unite(int x, int y);\nbool same(int x, int y);\nvoid solve();\nbool cmp(const Brige &b1, const Brige &b2);\n\nint main()\n{\n\tscanf(\"%d%d\",&n,&m);\n\tfor( int i=0; i<m; i++ )\n\t{\n\t\tscanf(\"%d%d%d\",&brige[i].u,&brige[i].v,&brige[i].day);\n\t\tcur_day = max( cur_day, brige[i].day);\n\t}\n\n\tsolve();\n\n\treturn 0;\n}\n\nvoid init(int n)\n{\n\tfor( int i=1; i<=n; i++ )\n\t{\n\t\tpar[i] = i;\n\t\theight[i] = 0;\n\t}\n}\n\nint find( int x )\n{\n\treturn x==par[x] ? x : par[x] = find(par[x]);\n}\n\nvoid unite(int x, int y)\n{\n\tx = find(x); y = find(y);\n\tif( x==y )\n\t\treturn;\n\tif( height[x]<height[y] )\n\t{\n\t\tpar[x] = y;\n\t}\n\telse\n\t{\n\t\tpar[y] = x;\n\t\tif( height[x]==height[y] )\theight[x]++;\n\t}\n}\n\nbool same(int x, int y)\n{\n\treturn find(x)==find(y);\n}\n\nbool cmp(const Brige &b1, const Brige &b2)\n{\n\treturn b1.day>b2.day;// 用>=作为条件会出错,原因是?\n}\n\nvoid solve()\n{\n\tinit(n);\n\tsort(brige,brige+m,cmp);\n\n\tint i = 0, ans = 0;\n\tbool flag;\n\twhile( cur_day>0 && i<m )\n\t{\n\t\tflag = false;\n\t\tfor( ; i<m; i++ )\n\t\t{\n\t\t\tif( cur_day != brige[i].day )\n\t\t\t{\n\t\t\t\tcur_day = brige[i].day;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t\tint u = brige[i].u, v = brige[i].v;\n\t\t\tbool temp = same(u,v);\n\t\t\tunite(u,v);\n\t\t\tif( flag )\tcontinue;\n\t\t\tif( temp^same(u,v) )\n\t\t\t{\n\t\t\t\tans++;\tflag = true;\n\t\t\t}\n\t\t}\n\t}\n\tprintf(\"%d\\n\",ans);\n}希望有大佬解答\n\n E 正文"}],"1437":[{"aid":"101881","title":"1437: 蓝桥杯历届试题-城市建设","date":"2024-01-15","likes":0,"views":716,"md":"S 正文\n原题链接：蓝桥杯历届试题-城市建设\n\n Server-side output Markdown text\n# 1437: 蓝桥杯历届试题-城市建设\n\n```cpp\n/*\n * 题目 1437: 蓝桥杯历届试题-城市建设\n * 生成树变形 -- 变形点/难点：两个消费维度 + 建设码头代价是点权而非边权 + 生成树算法理解。\n * 第一难点解决方案：拆。不建立码头和建立码头的代价取最小。如果存在包含关系可以只计算一次。但是不存在，建立码头可能单纯只是为了赚钱。\n * 点权 -> 边权：使用O(n^2)扫描建立边权 -> 不可能，数据量过大。\n * 方法2，建立超级源点0，假定0与所有点连接且点权为0。如此点权转置为边权。\n * 算法选择，Prim和Kruscal。按照题意是稀疏图，选Kruscal。\n * debug: 时间超限\n * 合并想的太简单了，优化一下。\n */\n#include<cstdio>\n#include<cstring>\n#include<iostream>\n#include<vector>\n#include<algorithm>\n#define MAX_N   100005\n#define MAX_M   100005\n#define CAN_NOT_BUILD 0\n#define SUPER_NODE    0\nstruct Edge {\n  int from, to;\n  int cost;\n\n  bool operator< (const Edge& other) const {\n    return this->cost < other.cost;\n  }\n  // Edge(int f, int t, int c) : from(f), to(t), cost(c) {};\n} e[MAX_N + MAX_M];\nint river[MAX_N], quick_set[MAX_N + MAX_M], rank[MAX_N + MAX_M];\nint n, m, cnt; // cnt只记录起连接作用的边，即负边不一定被cnt记录。\n\nint Belong(int x) {\n  while (x != quick_set[x]) {\n    quick_set[x] = quick_set[quick_set[x]];\n    x = quick_set[x];\n  }\n  return x;\n}\n\n// 合并集合fx, fy\nvoid union_set(int fx, int fy) {\n  if (rank[fx] > rank[fy]) quick_set[fy] = fx;\n  else quick_set[fx] = fy;\n  if (rank[fx] == rank[fy]) rank[fy] += 1;\n}\n\n// m 条边， n个点 生成树, 选用边数cnt\nint Kruscal(int m, int n) {\n  int res = 0;\n  for (int i = 0; i <= n; ++i) quick_set[i] = i; // initialize the quick_set\n  std::sort(e, e + m);\n\n  for (int i = 0; i < m; i++) {\n    int fx = Belong(e[i].from);\n    int fy = Belong(e[i].to);\n    if (fx != fy || e[i].cost < 0) {//负边铁赚，所以要加入\n      res += e[i].cost;\n      if (fx != fy) {\n        union_set(fx, fy);\n        cnt++;\n      }\n    }\n  } // 遍历 m 条边\n\n  return res;\n}\n\nint main() {\n  scanf(\"%d %d\", &n, &m);\n  for (int i = 0; i < m; i++)\n    scanf(\"%d%d%d\", &e[i].from, &e[i].to, &e[i].cost);\n  for (int i = 1; i <= n; i++)\n    scanf(\"%d\", &river[i]);\n\n  int flag = CAN_NOT_BUILD;\n  int cost1 = Kruscal(m, n);\n  if (cnt == n - 1) flag = !CAN_NOT_BUILD; // 有解\n\n  for (int i = 1; i <= n; i++) {\n    if (river[i] == -1) continue;\n    e[m].from = SUPER_NODE;\n    e[m].to = i;\n    e[m].cost = river[i];\n    m++;\n  }\n  // 建立码头 -- 题目保证一定有解 -- 第二次可不判断是否有解。\n  int cost2 = Kruscal(m, n);\n  printf(\"%d\\n\", flag ? std::min(cost1, cost2) : cost2);\n  return 0;\n}\n```\n\n E 正文"},{"aid":"91794","title":"Kruskal 求最小生成树+ 并查集","date":"2022-11-25","likes":0,"views":816,"md":"S 正文\n原题链接：蓝桥杯历届试题-城市建设\n\n解题思路:   看不加码头能不能构成最小生成树，如果不可以，则答案为加上码头和建路的最小生成树， ，，，如果可以，则在不加码头和  加上码头的最小生成树取最小值\n\n注意事项:建议把初始化码头和把码头的边加到边集中写在一个循环，不然会超时\n#include<iostream>\n#include<cstring>\n#include<algorithm>\n\nusing namespace std;\n\nconst int N = 1e4 + 10, M = 1e5 + 10, INF = 0x3f3f3f3f;\nint p[N], n, m, wi[N];\nstruct Edge {\n    int a, b, w;\n    //将边集按权值大小排序\n    bool operator < (const Edge& W)const {\n        return w < W.w;\n    }\n}e[M];\n\n//并查集\nint find(int x)\n{\n    if (p[x] != x) p[x] = find(p[x]);\n    return p[x];\n}\nint Kruskal(int node, int length)\n{\n    int res = 0;\n//初始化并查集\n    for (int i = 0; i <= node; i++)   p[i] = i;\n    sort(e, e + length);\n    int cnt = 0;\n    for (int i = 0; i < length; i++)\n    {\n        int a = e[i].a, b = e[i].b, c = e[i].w;\n        a = find(a), b = find(b);\n        //如果两个点不连通，将其连起来\n        if (a!=b)\n        {\n            p[a] = find(b);\n            res += c;\n            cnt++;\n        }\n        //如果两个点连通但是c<0即是赚钱的，也要加上\n        else if (c < 0)\n            res += c;\n    }\n//如果不能构成连通图，则返回INF\n    if (cnt < n - 1) return INF;\n    return res;\n}\nint main()\n{\n    scanf(\"%d %d\", &n, &m);\n    int cnt = m, ans;\n    //边集初始化\n    for (int i = 0; i < m; i++)\n    {\n        int x, y, w;\n        scanf(\"%d %d %d\", &x, &y, &w);\n        e[i] = { x,y,w };\n    }\n    int t = Kruskal(n, m);\n    //加上码头\n    for (int i = 1; i <= n; i++)\n    {\n        scanf(\"%d\", &wi[i]);\n        if (wi[i] != -1)\n        {\n            e[cnt].a = 0;\n            e[cnt].b = i;\n            e[cnt].w = wi[i];\n            cnt++;\n        }\n    }\n    //建路构成不了连通图，此时要加上码头\n    if (t == INF)\n    {\n        ans = Kruskal(n + 1, cnt);\n    }\n    //建路可以构成联通图，则在两个结果中取小的\n    else\n    {\n        ans = min(t, Kruskal(n + 1, cnt));\n    }\n\n    cout << ans << endl;\n    return 0;\n}\n\n E 正文"},{"aid":"85405","title":"java（最小生成树（由于码头性质引入中间点0））","date":"2022-03-18","likes":0,"views":685,"md":"S 正文\n原题链接：蓝桥杯历届试题-城市建设\n\n Server-side output Markdown text\n#### 二，城市建设（蓝桥杯）\n\n##### 题目描述\n\n栋栋居住在一个繁华的C市中，然而，这个城市的道路大都年久失修。市长准备重新修一些路以方便市民，于是找到了栋栋，希望栋栋能帮助他。\n\nC市中有n个比较重要的地点，市长希望这些地点重点被考虑。现在可以修一些道路来连接其中的一些地点，每条道路可以连接其中的两个地点。另外由于C市有一条河从中穿过，也可以在其中的一些地点建设码头，所有建了码头的地点可以通过河道连接。\n\n栋栋拿到了允许建设的道路的信息，包括每条可以建设的道路的花费，以及哪些地点可以建设码头和建设码头的花费。\n\n市长希望栋栋给出一个方案，使得任意两个地点能只通过新修的路或者河道互达，同时花费尽量小。\n\n样例说明\n建设第2、3、4条道路，在地点4、5建设码头，总的花费为9。\n\n##### 输入\n\n输入的第一行包含两个整数n, m，分别表示C市中重要地点的个数和可以建设的道路条数。所有地点从1到n依次编号。\n接下来m行，每行三个整数a, b, c，表示可以建设一条从地点a到地点b的道路，花费为c。若c为正，表示建设是花钱的，如果c为负，则表示建设了道路后还可以赚钱（比如建设收费道路）。\n接下来一行，包含n个整数w_1, w_2, …, w_n。如果w_i为正数，则表示在地点i建设码头的花费，如果w_i为-1，则表示地点i无法建设码头。\n\n输入保证至少存在一个方法使得任意两个地点能只通过新修的路或者河道互达。\n\n数据规模和约定\n对于100%的数据，1 < = n < = 10000，1 < = m < = 100000，-1000< =c< =1000，-1< =w_i< =1000，w_i≠0。\n\n##### 输出\n\n输出一行，包含一个整数，表示使得所有地点通过新修道路或者码头连接的最小花费。如果满足条件的情况下还能赚钱，那么你应该输出一个负数。\n\n##### 样例输入\n\n```\n5 5\n1 2 4\n1 3 -1\n2 3 3\n2 4 5\n4 5 10\n-1 10 10 1 1\n```\n\n##### 样例输出\n\n```\n9\n```\n\n##### 思路分析\n\n根据题意可以知道，这就是连接所有点，花费最小，但是需要注意的是，点与点之间可以通过道路连接，也可以通过码头连接，也就是假如\n\nA修建一条码头，B也修建一条码头，那么A可以到B，他们的权值为修建A码头的费用加上修建B码头的费用，但问题的关键在于，如果要修建码头，那么那些地方修呢？对此，我们可以分解一下，引入中间点0，既A修建一条码头，相当于A到中间点0，权值修建A的费用，B修建码头，那么AB就通过中间点0连接起来了，假如还有点c，c也修建码头，那么ABC就通过中间点0连通了\n\n还有可能存在这样的问题，只通过路，无法将全部的点连接起来，所以我们需要统计一下更新的点\n\n还有可能存在这样的问题，只通过路比修码头费用要少\n\n测试用例\n5 10\n5 2 8\n4 5 8\n2 5 10\n1 4 4\n5 3 5\n1 2 9\n1 5 8\n5 1 2\n1 3 5\n4 3 12\n-1 -1 -1 18 11\n建立码头\n5->1     2\n1->4     4\n5->3     5\n5->2     8\n5->0     11\n30\n不建码头\n5->1     2\n1->4     4\n5->3     5\n5->2     8\n19\n\n修码头比只修路费用要少\n\n测试用例2\n5 5\n1 2 4\n1 3 -1\n2 3 3\n2 4 5\n4 5 10\n-1 10 10 1 1\n建立码头\n1->3     -1\n4->0     1\n5->0     1\n2->3     3\n2->4     5\n不建码头\n1->3     -1\n2->3     3\n2->4     5\n4->5     10\n\n所以两种情况费用我们都要计算，最后取最小值\n\n还有的路不仅不费钱，还赚钱，所以不管是否连通，我们都要修\n\n可能会想到思路二，那就是有码头的和有码头的直接算成一条边，权值为他们的和，但是这样有一个问题\n\n假如有三个点123中间一条河，123之间没有路，每个点修建码头的费用依次为f1,f2,f3,那么他们连通的费用为f1+f2+f3\n\n如果直接枚举12连成一条边，13连成一条边，23连成一条边，那么连通他们的最小代价必定是这三条边中两条边的权值相加，结果必定大于f1+f2+f3，所以该思路不正确，所以这种问题还是需要引入中间点0\n\n##### 代码实现\n\n```\nimport java.util.ArrayList;\nimport java.util.Comparator;\nimport java.util.List;\nimport java.util.PriorityQueue;\nimport java.util.Queue;\nimport java.util.Scanner;\n\npublic class Main {\n\tpublic int[] parent = null;\n\n\tpublic static void main(String[] args) {\n\t\tScanner sca = new Scanner(System.in);\n\t\t// 将所有可能的边加入优先级队列\n\t\tQueue<EDGE> queue = new PriorityQueue<>(new Comparator<EDGE>() {\n\n\t\t\t@Override\n\t\t\tpublic int compare(EDGE o1, EDGE o2) {\n\t\t\t\t// TODO Auto-generated method stub\n\t\t\t\treturn o1.quanZhi - o2.quanZhi;\n\t\t\t}\n\t\t});\n\n\t\tint n = sca.nextInt();\n\t\tint m = sca.nextInt();\n\t\tfor (int i = 0; i < m; i++) {\n\t\t\tqueue.offer(new EDGE(sca.nextInt(), sca.nextInt(), sca.nextInt()));\n\t\t}\n\t\t// 由于能建码头的点没有终点，我们将0作为临时点，费用为建码头的费用\n\t\tfor (int i = 1; i <= n; i++) {\n\t\t\tint t = sca.nextInt();\n\t\t\tif (t != -1) {\n\t\t\t\tqueue.offer(new EDGE(i, 0, t));\n\t\t\t}\n\t\t}\n\t\tMain main = new Main();\n\t\t// 2.并查集三方法\n\t\tmain.init(n);\n\t\t//创建一个新队列并将旧队列中的元素添加进新队列，旧队列用于不计算码头，新队列用于计算码头\n\t\tQueue<EDGE> queue2 = new PriorityQueue<>(queue);\n\t\t// 3.使用最小生成树算法\n\t\t// 不计算码头\n\t\tint result1 = main.Kruskal(queue, false, n);\n\t\t// 计算码头\n\t\t//再次使用，需要初始化parent，\n\t\tmain.init(n);\n\t\tint result2 = main.Kruskal(queue2, true, n);\n\t\tSystem.out.println(Math.min(result1, result2));\n\n\t}\n\n\tprivate int Kruskal(Queue<EDGE> queue, boolean flag, int n) {\n\t\t// TODO Auto-generated method stub\n\t\tint result = 0;\n\t\t// 记录连通了的边\n\t    int count=0;\n\t    List<EDGE>list=new ArrayList<>();\n\t\twhile (!queue.isEmpty()) {\n\t\t\tEDGE edge = queue.poll();\n\t\t\tif (edge.end == 0 && flag == false) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tif (find(edge.start) != find(edge.end)) {\n\t\t\t\tunion(edge.start, edge.end);\n\t\t\t\tresult += edge.quanZhi;\n\t\t\t\tlist.add(new EDGE(edge.start,edge.end,edge.quanZhi));\n\t\t\t\tcount++;\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\t// 如果能赚钱，即使连通也要建\n\t\t\tif (edge.quanZhi < 0) {\n\t\t\t\tresult += edge.quanZhi;\n\t\t\t\tlist.add(new EDGE(edge.start,edge.end,edge.quanZhi));\n\t\t\t}\n\n\t\t}\n\t\t//如果不建码头，也就是无中间点，也就是只用更新n个点，n-1条边，如果更新低于这些，说明无法连通\n\t\tif(count!=n-1&&flag==false) {\n\t\t\treturn Integer.MAX_VALUE;\n\t\t}\n//\t\t//如果建码头，也就是有中间点，也就是只用更新n+1个点，n条边，如果更新低于这些，说明无法连通\n//\t\tif(count!=n&&flag==true)\n\n（正文过长，已截断，全文见原文链接）"},{"aid":"82458","title":"城市建设-通过kruskal算法生成最小生成树 [Java][超详细注解]","date":"2022-01-06","likes":0,"views":2130,"md":"S 正文\n原题链接：蓝桥杯历届试题-城市建设\n\n解题思路:\n首先是具有权值的图，然后还需要算出最小的造价。\n\n那么可以很好想到需要生成一个最小生成树，当然这题的最小生成树比较特殊，\n因为这里的道路权重如果小于0时，是可以赚钱的，所以遇到能赚钱的路，就必须建，不管是不是联通了。\n\n生成最小生成树这道题用prim和kruskal算法都可以，反正只需要生成最小生成树就可以。\n\n然后就是分情况\n不建桥 2. 建桥\n\n然后选择两种情况下造价较小的\n注意事项:\n认真读题，河道没有明确的连接关系，所以我们可以用 0 这个点作为他们的衔接点，\n0 这个点没有权值，所以价格就是输入的那个码头的造价。如果觉得文字不好理解，可以直接看代码。\n\n参考代码:\nimport java.util.*;\n\npublic class 城市建设_1437 {\n\n    public static ArrayList<Edge> edges = new ArrayList<>();\n\n    public static int[] vertices;\n\n    public static int n;\n\n    // 题目地址：https://www.dotcpp.com/oj/problem1437.html\n    // 思路：使用kruskal算法生成最小生成树\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        n = scanner.nextInt() + 1;\n        int m = scanner.nextInt();\n        vertices = new int[n];\n        // 输入桥梁\n        for (int i = 0; i < m; i++) {\n            int from = scanner.nextInt();\n            int to = scanner.nextInt();\n            int price = scanner.nextInt();\n            edges.add(new Edge(from, to, price));\n        }\n\n        // 输入码头造价\n        // 记录码头的数量\n        int terNum = 0;\n        for (int i = 1; i < n; i++) {\n            int terPrice = scanner.nextInt();\n            // 如果可以建码头，则码头也算是一条路，但是起点我们并不知道\n            if (terPrice != -1) {\n                edges.add(new Edge(i, 0, terPrice));\n                terNum++;\n            }\n        }\n\n        // 排序\n        edges.sort(Comparator.comparingInt((o) -> o.price));\n\n        // 不建码头的情况下\n        int sum1 = kruskal(n, false);\n        // 建码头的情况下\n        int sum2 = kruskal(n + 1, true);\n        // 选一个最小值\n        System.out.println(Math.min(sum1, sum2));\n    }\n\n    public static int kruskal(int n, boolean isBuildTer) {\n        // 初始化并查集\n        initVertex();\n        int sum = 0;\n        for (Edge edge : edges) {\n            // 如果他的 to==0 并且本次kruskal是不建桥的，就continue\n            if (edge.to == 0 && !isBuildTer) continue;\n            if (!isSame(edge)) {\n                union(edge);\n                sum += edge.price;\n                n--;\n            } else {\n                if (edge.price < 0) {\n                    // 如果这条路是可以赚钱的，则不管是否联通，都建造\n                    sum += edge.price;\n                }\n            }\n        }\n        // 这里--n是因为n为了数据输入的时候方便操作在输入的时候+1了\n        if (--n > 1) {\n            return Integer.MAX_VALUE;\n        } else {\n            return sum;\n        }\n    }\n\n    // 初始化并查集用的数组\n    public static void initVertex() {\n        for (int i = 0; i < n; i++) {\n            vertices[i] = i;\n        }\n    }\n\n    // Quick Union 实现形式 快速链接方式\n    // 查找根节点\n    public static int find(int v) {\n        while (v != vertices[v]) {\n            v = vertices[v];\n        }\n        return v;\n    }\n\n    // 判断是否相连\n    public static boolean isSame(Edge edge) {\n        return find(edge.from) == find(edge.to);\n    }\n\n    // 将edge的from和to连接\n    public static void union(Edge edge) {\n        vertices[find(edge.from)] = find(edge.to);\n    }\n\n    // 边对象\n    private static class Edge {\n        public int from;\n        public int to;\n        public int price;\n\n        public Edge(int from, int to, int price) {\n            this.from = from;\n            this.to = to;\n            this.price = price;\n        }\n    }\n}\n\n E 正文"},{"aid":"80193","title":"城市建设AC代码(kruskal算法+并查集)","date":"2021-10-01","likes":0,"views":761,"md":"S 正文\n原题链接：蓝桥杯历届试题-城市建设\n\n对于本题样例\n虚构地点6连接1,2,3,4,5，从而代替码头的功能(例如1,2,3，建设码头，等价于6站点建设三座联通1,2,3,的道路)\n5 5\n1 2 4\n1 3 -1\n2 3 3\n2 4 5\n4 5 10\n-1 10 10 1 1\n\n我们使用kruskal算法：\n选取花费最低的路径1-3，此时总花费sum=-1；\n已连接站点：1-3\n继续取最小值的路径6-4,此时总花费sum=0；\n已连接站点：1-3,6-4\n继续取最小值的路径6-5,此时总花费sum=1；\n已连接站点：1-3,6-4-5\n继续取最小值的路径2-3,此时总花费sum=4；\n已连接站点：1-2-3,6-4-5\n继续取最小值的路径1-2，1和2已连接，不操作\n继续取最小值的路径2-4此时总花费sum=9；\n已连接站点：1-2-3-4-5-6\n故sum=9\n特别注意：1.题目所求为最大花费，因此只要道路的花费小于0，不论站点是否已有道路，都应该在建设道路\n                 2.如果出现代替码头城市只连接一个站点的情况(即只建了一个码头)，应该将改码头的花费减去\n                 3.提前对所有道路价值排序（只能用快速排序，否则会超时），且对于码头花费小于0的不进行排序\n\n全代码如下（排序部分抄了大佬作业）：\n#include<iostream>\n#include<vector>\n#include <algorithm>\nusing namespace std;\nclass Node\n{\npublic:\n\tint a;\n\tint b;\n\tint c;\n};\nNode node[200001];\nint n, m, w;\nint fa[100001];\nvector<Node>e;\nvoid ini()\n{\n    for (int i = 1; i <= n+1; i++)\n    {\n        fa[i] = i;\n    }\n}\nint find(int i)\n{\n    if (fa[i] == i)\n        return i;\n    else\n    {\n        fa[i] = find(fa[i]);\n        return fa[i];\n    }\n}\nvoid unionn(int x,int y)\n{\n    int _x = find(x);\n    int _y = find(y);\n    fa[_x] = _y;\n}\nbool comp(const Node& e1, const Node& e2) {\n    return e1.c < e2.c;//从小到大\n}\nint main()\n{\n\tcin >> n >> m;\n    for (int i = 0; i < m; i++)\n    {\n        cin >> node[i].a >> node[i].b >> node[i].c;\n        e.push_back(node[i]);\n    }\n    int t = m;\n    for (int i = 1; i <= n; i++)\n    {\n        cin >> w;\n        if (w != -1)\n        {\n            node[t].a = n + 1;\n            node[t].b = i;\n            node[t].c = w;\n            e.push_back(node[t]);\n            t++;\n        }\n    }\n    sort(e.begin(),e.end(),comp);\n    ini();\n    int sum = 0;\n    int i = 0;\n    int j = 0;\n    int temp = 0;\n    for (; i < e.size(); i++)\n    {\n        if (e[i].c <= 0)\n        {\n            if (e[i].a != n + 1)\n            {\n                sum += e[i].c;\n                unionn(e[i].a, e[i].b);\n            }\n        }\n        else\n        {\n            break;\n        }\n    }\n    for (; i < t; i++)\n    {\n        if (find(e[i].a) != find(e[i].b))\n        {\n            if (e[i].a == n + 1)\n            {\n                j++;\n                temp = e[i].c;\n            }\n            if (j >= 2)\n                break;\n            sum += e[i].c;\n            unionn(e[i].a, e[i].b);\n        }\n    }\n    for (; i < t; i++)\n    {\n        if (find(e[i].a) != find(e[i].b))\n        {\n            sum += e[i].c;\n            unionn(e[i].a, e[i].b);\n        }\n    }\n    if (j == 1)\n        sum-=temp;\n    cout << sum;\n\treturn 0;\n}\n\n E 正文"}],"1439":[{"aid":"108242","title":"小朋友排队  (归并排序)","date":"2025-01-15","likes":0,"views":741,"md":"S 正文\n原题链接：蓝桥杯历届试题-小朋友排队\n\n Server-side output Markdown text\n    #include <bits/stdc++.h>\n    using namespace std;\n    typedef long long ll;\n    const int N = 1e5 + 10;\n    int n;\n    struct node\n    {\n        int h, idx; // h-身高，idx-上一次位置\n        ll len; // 移动次数\n    } a[N], b[N];\n\n    // 归并函数，将数组 a[l...mid] 和 a[mid+1...r] 合并为一个有序数组\n    void merge(int l, int mid, int r)\n    {\n        int i = l, j = mid + 1;\n        int k = l;\n\n        // 遍历两个子数组，将较小的元素放入临时数组 b 中\n        while (i <= mid && j <= r) {\n            if (a[i].h <= a[j].h) {\n                b[k++] = a[i++];\n            } else {\n                b[k++] = a[j++];\n            }\n        }\n\n        // 将剩余的元素放入临时数组 b 中\n        while (i <= mid) {\n            b[k++] = a[i++];\n        }\n        while (j <= r) {\n            b[k++] = a[j++];\n        }\n\n        // 将临时数组 b 中的元素复制回原数组 a 中\n        for (int p = l; p <= r; p++) {\n            a[p] = {b[p].h, p, b[p].len + abs(b[p].idx - p)};\n        }\n    }\n\n    // 归并排序函数\n    void merge_sort(int l, int r)\n    {\n        if (l >= r) return;\n        int mid = l + r >> 1;\n        merge_sort(l, mid);\n        merge_sort(mid + 1, r);\n        merge(l, mid, r);\n    }\n\n    int main()\n    {\n        cin>>n;\n        for (int i = 1; i <= n; i++)\n        {\n            cin>>a[i].h;\n            a[i].idx = i;\n            a[i].len = 0; // 初始化移动次数为 0\n        }\n        merge_sort(1, n);\n        ll res = 0;\n        for (int i = 1; i <= n; i++)\n            res += (a[i].len + 1) * a[i].len / 2;\n        cout<<res<<endl;\n        return 0;\n    }\n\n E 正文"},{"aid":"99364","title":"参考c语言写的","date":"2023-11-03","likes":0,"views":654,"md":"S 正文\n原题链接：蓝桥杯历届试题-小朋友排队\n\ndef add(d, i, x, maxh):\n    while i <= maxh + 1:\n        d[i] += x\n        i += i & -i\n\ndef _sum(d, i):\n    res = 0\n    while i > 0:\n        res += d[i]\n        i -= i & -i\n    return res\n\nn = int(input())\na = list(map(int, input().split()))\nd = [0] * 1000005\nlr = [0] * 100005\nmaxh = 0\n\nfor i in range(n):\n    a[i] += 1\n    maxh = max(maxh, a[i])\n\nfor i in range(n):\n    add(d, a[i], 1, maxh)\n    lr[i] += i + 1 - _sum(d, a[i])\n\nd = [0] * (maxh + 5)\n\nfor i in range(n - 1, -1, -1):\n    add(d, a[i], 1, maxh)\n    lr[i] += _sum(d, a[i] - 1)\n\nans = 0\nfor i in range(n):\n    k = lr[i]\n    ans += k * (k + 1) // 2  # 使用 // 进行整数除法，得到整数结果\n\nprint(ans)\n\n E 正文"},{"aid":"85813","title":"树状数组，python","date":"2022-03-27","likes":0,"views":824,"md":"S 正文\n原题链接：蓝桥杯历届试题-小朋友排队\n\n解题思路:\n\n注意事项:\n\n参考代码:\nn=int(input())\nh=list(map(int,input().split()))\nmaxh=max(h)\ncnt=[0]*(n)\nc=[0]*(maxh+2)#c[i]代表的是身高i-1\ndef lowbit(i):\n    return i&(-i)\ndef update(i,num):\n    while(i<=maxh+1):\n        c[i]+=num\n        i+=lowbit(i)\ndef getsum(i):#计算的是原始数组[0,i]的和\n    sum=0\n    while(i>0):\n        sum+=c[i]\n        i-=lowbit(i)\n    return sum\nfor i in range(n):#左边要统计比它大的\n    update(h[i]+1,1)\n    sum=getsum(h[i]+1)\n    cnt[i]+=i+1-sum\nc=[0]*(maxh+2)\nfor i in range(n-1,-1,-1):\n    update(h[i]+1,1)\n    sum=getsum(h[i])\n    cnt[i]+=sum\nans=0\nfor i in range(len(cnt)):\n    ans+=((1+cnt[i])*cnt[i]//2)\nprint(ans)\n\n E 正文"},{"aid":"85526","title":"1439: 蓝桥杯历届试题-小朋友排队(权值线段树) Java AC代码","date":"2022-03-20","likes":0,"views":1009,"md":"S 正文\n原题链接：蓝桥杯历届试题-小朋友排队\n\n解题思路:尝试使用了比树状数组功能更强大的线段树，线段树可以解决所有用树状数组解决的题，唯一缺点就是需要开辟4*n的大小才能保证不溢出。\n注意事项:\n对于本题来说，即求数组中某数的逆序对，然后求其等差数列的和即可。本代码没有构造权值线段树的过程，而是直接进行update操作，免去了建树的时间。需要注意的是，需要对给定数组进行两次遍历，一次得到前置逆序，一次得到后置逆序，最后拼接结果即可。\n看到有佬还是用了lazy标记让我很不解。。为什么对这样单点修改更新的操作还需要延迟呢？\n总的来说，本题算是一道树状数组和线段树的模板题\n参考代码:\nimport java.io.*;\n\n// 蓝桥杯历届试题-小朋友排队 - C语言网 (dotcpp.com)\npublic class Main {\n    static StreamTokenizer cin;\n    static PrintWriter out;\n    static int n; // 小朋友的个数\n    static int[] arr;  // 小朋友身高\n    static long[] cnt; // 每个小朋友最少需要交换的次数\n    static int[] treeArr;\n    static int maxN = -1;  // 存储上值域\n    public static void main(String[] args) throws IOException {\n        cin = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));\n        out = new PrintWriter(new OutputStreamWriter(System.out));\n        n = nextInt();\n        arr = new int[n+1];\n        cnt = new long[n+1];\n        for(int i = 1; i < n+1; i++){\n            int num = nextInt();\n            arr[i] = num;\n            maxN = Math.max(maxN, num);\n        }\n        treeArr = new int[(maxN << 2)+10];\n        for(int i = 1; i < n+1; i++){\n            update(0, 0, maxN, arr[i]);\n            // 存储i左边比arr[i]大的元素\n            cnt[i] += query(0, 0, maxN, arr[i]+1, maxN);\n        }\n        // 重构\n        treeArr = new int[4*maxN +10];\n        for(int i = n; i > 0; i--){\n            update(0, 0, maxN, arr[i]);\n            // 存储i右边比arr[i]小的元素\n            cnt[i] += query(0, 0, maxN, 0, arr[i]-1);\n        }\n        long res = 0;\n        for(int i = 1; i < n+1; i++){\n            res += cnt[i]*(cnt[i] + 1)/2;\n        }\n        out.println(res);\n        out.flush();\n\n    }\n\n    // 单点修改, 不需要lazy标记, L和R为此节点值域范围\n    static void update(int node, int L, int R, int value){\n        if(L == value && R == value){  // 叶子\n            treeArr[node]++;  // 重复值++\n            return;\n        }\n        int mid = (L+R) >> 1;\n        int leftNode = (node << 1) + 1;\n        int rightNode = leftNode + 1;\n        if(value = L)\n            update(leftNode, L, mid, value);  // 更新左子树\n        if(value = mid+1)\n            update(rightNode, mid+1, R, value);  // 更新右子树\n        treeArr[node] = treeArr[leftNode] + treeArr[rightNode];\n    }\n\n    // 查询[value, maxN]间的元素个数\n    static long query(int node, int L, int R, int QL, int QR){\n        if(QL > R  || L > QR)\n            return 0;\n        if(QL = R)  // 完全覆盖\n            return treeArr[node];\n        int mid = (L + R) >> 1;\n        int leftNode = (node << 1) + 1;\n        int rightNode = leftNode + 1;\n        long result = 0;\n        if(!(QL > mid))\n            result += query(leftNode, L, mid, QL, QR);\n        if(!(QR < mid+1))\n            result += query(rightNode, mid+1, R, QL, QR);\n        return result;\n    }\n\n    static int nextInt() throws IOException{\n        cin.nextToken();\n        return (int)cin.nval;\n    }\n}\n\n E 正文"},{"aid":"85327","title":"树状数组（注意身高为0）","date":"2022-03-16","likes":0,"views":621,"md":"S 正文\n原题链接：蓝桥杯历届试题-小朋友排队\n\n Server-side output Markdown text\n```cpp\n#include<bits/stdc++.h>\nusing namespace std;\ntypedef long long ll;\n#define lowbit(x) ((x)&-(x))\nconst int N=1e6+5;\nint n;\nint tree[N],num[N],a[N];\nvoid update(int x,int d){\n  while(x<=N){\n    tree[x]+=d;\n    x+=lowbit(x);\n  }\n}\nint sum(int x){\n  int s=0;\n  while(x>0){\n    s+=tree[x];\n    x-=lowbit(x);\n  }\n  return s;\n}\n\nint main()\n{\n  cin>>n;\n  for(int i=1;i<=n;i++){\n    cin>>a[i];\n    a[i]++;\n  }\n  ll ans=0;\n  for(int i=n;i>0;i--){\n    num[i]+=sum(a[i]-1);\n    update(a[i],1);\n  }\n  memset(tree,0,sizeof(tree));\n  for(int i=1;i<=n;i++){\n    num[i]+=sum(N-1)-sum(a[i]);\n    update(a[i],1);\n  }\n  for(int i=1;i<=n;i++){\n    ans+=(ll)num[i]*(num[i]+1)/2;\n  }\n  cout<<ans;\n  return 0;\n}\n\n```\n\n E 正文"}],"1443":[{"aid":"106535","title":"蓝桥杯历届试题-数字游戏（暴力法）","date":"2024-10-07","likes":0,"views":938,"md":"S 正文\n原题链接：蓝桥杯历届试题-数字游戏\n\n解题思路:暴力循环\n\n注意事项:\n\n参考代码:\n#include<stdio.h>\nint main()\n{\n    int n,k,t;\n    scanf(\"%d%d%d\",&n,&k,&t);\n    int a[10000000]; a[1]=1;\n    int sum=0;\n    for(int i=1;i<=n*(t-1)+1;i++)\n    {\n        a[i]=a[i-1]+i-1;\n    }\n    for(int i=1;i<=n*(t-1)+1;i++)\n    {\n        if(a[i]/k!=0)\n        {\n            a[i]=a[i]-(a[i]/k)*k;\n        }\n    }\n    for(int i=1;i<=n*(t-1)+1;i++)\n    {\n        if(i%n==1)\n        {\n            sum+=a[i];\n        }\n    }\n    printf(\"%d\",sum);\n}\n\n E 正文"},{"aid":"101364","title":"java 蓝桥杯历届试题-数字游戏","date":"2023-12-30","likes":0,"views":632,"md":"S 正文\n原题链接：蓝桥杯历届试题-数字游戏\n\n解题思路:\n\n注意事项:数据类型！时间限制！等差数列求和公式【（首项+末项）*项数/2】\n\n参考代码:\nimport java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int k = sc.nextInt();\n        int t = sc.nextInt();\n        long sum = 1;\n        long sum2 = 0;\n        long m = (long) (1 + n) * n / 2;\n        for (int i = 1; i <= t; i++) {\n            sum2 += sum;\n            sum += m;\n            m += (long) n * n;\n            while (sum > k - 1) {\n                sum = sum % k;\n            }\n        }\n        System.out.println(sum2);\n    }\n}\n\n E 正文"},{"aid":"101120","title":"c代码记录之数字游戏","date":"2023-12-21","likes":1,"views":693,"md":"S 正文\n原题链接：蓝桥杯历届试题-数字游戏\n\n Server-side output Markdown text\n本质上是一道挺水的题，浅表做题过程\n\nn: 报数人数\nk：报到（k-1）时，下一次从0开始报数\nt：栋栋报过的次数\nsum：栋栋报过的数之和\n\nfind 1\n假设不从零重报，第m次报数为baoshu=1+1+2+3+4+5+6+...+（m-1）\n从零重报，只需对baoshu取模操作即为第m次实际报数：baoshu%k\n所以有了如下代码\n    #include<stdio.h>\n    int main()\n    {\n        long long baoshu,i,sum=1,n,k,t;\n        scanf(\"%lld%lld%lld\",&n,&k,&t);\n        for(i=2;i<=t;i++){\n            baoshu=((i-1)*n+1)*((i-1)*n)/2+1;\n            sum+=baoshu%k;\n        }\n        printf(\"%lld\",sum);\n    \treturn 0;\n    }\n![](/image_editor_upload/20231221/20231221101939_59793.png)\n因为求和后导致baoshu实在太大，哪怕定义为long long型，都会超范围报错，需要优化代码\n\nfind 2\n刚才baoshu是理论报数，数值太大，现在更改为实际报数\n栋栋这次的实际报数+后续应加的n个数的和，再取模即为下次报数的实际报数\n\n代码如下\n    #include<stdio.h>\n    int main()\n    {\n        long long baoshu=1,i,sum=1,n,k,t;\n        scanf(\"%lld%lld%lld\",&n,&k,&t);\n        for(i=2;i<=t;i++){\n            baoshu=(baoshu+((i-1)*n+(i-2)*n+1)*n/2)%k;\n            sum+=baoshu;\n        }\n        printf(\"%lld\",sum);\n    \treturn 0;\n    }\n\n E 正文"},{"aid":"95383","title":"Python解决该问题，观察出等差数列的方法直接写出，较为简洁","date":"2023-03-29","likes":1,"views":792,"md":"S 正文\n原题链接：蓝桥杯历届试题-数字游戏\n\n解题思路:\n正常的以一个一个小朋友说什么数字来计算的话虽然简单但是会超出内存，超时等问题，最好的方法还是找到数列的规律，写出简洁的数学公式：\n![](https://blog.dotcpp.com/uploads/20230329/1680093901578147.jpg)\n注意事项:\n\n参考代码:\nn,k,t = map(eval, input().split())\na1 = 1\ntemp = []\nfor i in range(0, t):\n    an = (a1+(a1*n*i + ((n*i*(n*i-1)*1)//2)))%k # an对应的是每一次轮到栋栋的数\n    temp.append(an)  # 将每一次的栋栋的数都统计到一个数列中去\nprint(int(sum(temp)))\n\n E 正文"},{"aid":"91597","title":"通俗易懂C++","date":"2022-11-17","likes":3,"views":1182,"md":"S 正文\n原题链接：蓝桥杯历届试题-数字游戏\n\n#include<iostream>\nusing namespace std;\nint main()\n{\n    // 用long long int防止溢出错误\n    long long int n,k,T;\n    // 表示栋栋说出的数\n   long long int a=1;\n    //   用于表示间隔数目\n   long long int temp=1;\n    //   代表栋栋每次输出数字的数目和，初始值为栋栋第一次说出的数1\n   long long int sum=1;\n   cin>>n>>k>>T;\n    //   栋栋第一次说出的数已经作为初始值，所以要少一次循环\n   T=T-1;\n   while(T--){\n    // 如果直接枚举所有人说出的数值，就会超时，所以要找到栋栋说出数字的规律\n    /* 栋栋说出的数=(栋栋上一轮的数+人数*(间隔数+这一轮最后一个间隔数)/2)%k，因为以每次完成\n    栋栋说的数为一个循环,人数*(间隔数+这一轮最后一个间隔数)/2经过例子找规律，为等差数列*/\n    a=(a+n*(temp+(temp+n-1))/2)%k;\n    temp=temp+n;\n    sum+=a;\n   }\n   cout<<sum;\n    return 0;\n}\n\n E 正文"}],"1445":[{"aid":"103937","title":"1445: 蓝桥杯历届试题-最大子阵","date":"2024-03-28","likes":0,"views":662,"md":"S 正文\n原题链接：蓝桥杯历届试题-最大子阵\n\n Server-side output Markdown text\n    #include<iostream>\n    using namespace std;\n    int n,m,ans=-5005,sum;\n    int a[505][505];\n    int pre[505][505];\n    int main()\n    {\n        cin>>n>>m;\n        for(int i=1;i<=n;i++){\n            for(int j=1;j<=m;j++){\n                cin>>a[i][j];\n                ans=max(ans,a[i][j]);\n            }\n        }\n        if(ans<0){\n            cout<<ans<<endl;\n        }else{\n            for(int i=1;i<=n;i++){\n                for(int j=1;j<=m;j++){\n                    pre[i][j]=pre[i-1][j]+a[i][j];\n                }\n            }\n            for(int i=1;i<=n;i++){\n                for(int j=i;j<=n;j++){\n                    sum=0;\n                    for(int k=1;k<=m;k++){\n                        if(sum+pre[j][k]-pre[i-1][k]<0){\n                            sum=0;\n                        }else{\n                            sum+=pre[j][k]-pre[i-1][k];\n                        }\n                        ans=max(ans,sum);\n                    }\n                }\n            }\n            cout<<ans<<endl;\n        }\n        return 0;\n    }\n\n E 正文"},{"aid":"95431","title":"1445:————蓝桥杯历届试题-最大子阵(仿)","date":"2023-03-31","likes":0,"views":769,"md":"S 正文\n原题链接：蓝桥杯历届试题-最大子阵\n\n Server-side output Markdown text\n    import java.util.Scanner;\n\n    public class Main {\n    \tpublic static void main(String[] args) {\n    \t\tScanner scanner = new Scanner(System.in);\n    \t\tint n = scanner.nextInt(); // 矩阵的行数\n    \t\t  int m = scanner.nextInt(); // 矩阵的列数\n    \t\t  int[][] arr = new int[n][m]; // 矩阵\n    \t\t  for (int i = 0; i < n; i++) {\n    \t\t       for (int j = 0; j < m; j++) {\n    \t\t           arr[i][j] = scanner.nextInt();\n    \t\t       }\n    \t\t  }\n    \t\t  int max = Integer.MIN_VALUE; // 最大子阵的和\n    \t\t  for (int i = 0; i < n; i++) {\n    \t\t       int[] a = new int[m]; // 存放每一列的和\n    \t\t       for (int j = i; j < n; j++) {\n    \t\t    \t   int sum = 0; // 当前子阵的和\n    \t\t           for (int k = 0; k < m; k++) {\n    \t\t               a[k] += arr[j][k]; // 更新每一列的和\n    \t\t               sum += a[k]; // 计算当前子阵的和\n    \t\t               if (sum > max){\n    \t\t            \t   max = sum;\n    \t\t               } // 更新最大子阵的和\n    \t\t               if (sum < 0){\n    \t\t            \t   sum = 0;\n    \t\t               }\n    \t\t           }\n    \t\t       }\n    \t\t  }\n    \t\t  System.out.println(max);\n    \t}\n    }\n\n E 正文"},{"aid":"94747","title":"最大段子和求法","date":"2023-03-11","likes":1,"views":800,"md":"S 正文\n原题链接：蓝桥杯历届试题-最大子阵\n\n解题思路:\n我们需要额外设立一个二维数组来存放每一列数组的和如下所示：\n比如先假设一个二位数组：\n1 2 3\n4 5 6\n7 8 9\n那么这个额外的数组就应该是：\n1 2 3\n5 7 9\n12 15 18\n代码实现：\nfor(n=1;n<=j;n++){\nfor(m=1;m<=k;m++){\nif(n==1){\nb[n][m]=a[n][m];\ncontinue;\n}\nb[n][m]=b[n-1][m]+a[n][m];\n}\n}\n最后用最大段子和思想把>0的留下，小于0的去除在进行比较即可。\n注意事项:\n\n参考代码:\n#include<stdio.h>\n\tint main(){\n\t\tint j,k,n,m,a[1000][1000],b[1000][1000];\n\t\tscanf(\"%d %d\",&j,&k);\n\t\tfor(n=1;n<=j;n++){\n\t\t\tfor(m=1;m<=k;m++){\n\t\t\t\tscanf(\"%d\",&a[n][m]);\n\t\t\t}\n\t\t}\n\t\tfor(n=1;n<=j;n++){\n\t\t\tfor(m=1;m<=k;m++){\n\t\t\t\tif(n==1){\n\t\t\t\t\tb[n][m]=a[n][m];\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\t\tb[n][m]=b[n-1][m]+a[n][m];\n\t\t\t}\n\t\t}\n\t\tint max=0,sum=0,z,temp=-99999;\n\t\tfor(n=1;n<=j;n++){\n\t\t\tfor(m=n;m<=j;m++){\n\t\t\t\tfor(z=1;z<=k;z++){\n\t\t\t\t\tsum=b[m][z]-b[n-1][z];\n\t\t\t\t\tif(temp>=0){\n\t\t\t\t\t\ttemp=temp+sum;\n\t\t\t\t\t\tif(temp>max) max=temp;\n\t\t\t\t\t}\n\t\t\t\t\telse if(temp<0){\n\t\t\t\t\t\ttemp=sum;\n\t\t\t\t\t\tif(temp>max) max=temp;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\ttemp=0;\n\t\t\t}\n\t\t}\n\t\tprintf(\"%d\",max);\n\t\treturn 0;\n\t}\n\n E 正文"},{"aid":"94334","title":"蓝桥杯历届试题-最大子阵","date":"2023-02-26","likes":0,"views":647,"md":"S 正文\n原题链接：蓝桥杯历届试题-最大子阵\n\n解题思路:一维和加最大子串和\n\n注意事项:\n\n参考代码:\n#include<iostream>\n#include<unordered_map>\n#include<vector>\n#include<deque>\n#include<algorithm>\n#include<map>\n#include<set>\n#include<cstring>\n#include<cmath>\n#include<queue>\n#include<stack>\n#define int  long long\n\nusing namespace std;\nconst int N=550;\nint map1[N][N],n,m;\n\nvoid solve(){\n    cin>>n>>m;\n    for(int i=1;i<=n;i++){\n        for(int j=1;j<=m;j++){\n            scanf(\"%lld\",&map1[i][j]);\n            map1[i][j]=map1[i][j]+map1[i-1][j];//转化为一维子序列，只需要求一维子序列的最大值\n            //map1[i][j]=map1[i][j]+map1[i-1][j]+map1[i][j-1]-map1[i-1][j-1];\n        }\n    }\n    int max1=-99999;\n    for(int i=0;i<=n;i++){\n        for(int j=i+1;j<=n;j++){\n            int x=map1[j][1]-map1[i][1];\n            max1=max(x,max1);\n            for(int k=2;k<=m;k++){\n                x=max(map1[j][k]-map1[i][k],x+map1[j][k]-map1[i][k]);\n                max1=max(max1,x);\n            }\n        }\n    }\n    cout<<max1<<endl;\n}\n\nsigned main(){\n    int t=1;\n    //cin>>t;\n    while(t--){\n        solve();\n    }\n}\n\n E 正文"},{"aid":"88163","title":"前缀和思想","date":"2022-06-10","likes":0,"views":715,"md":"S 正文\n原题链接：蓝桥杯历届试题-最大子阵\n\n注意事项:\n\nif(ans < 0) ans = 0;\n//当ans<0时，如果继续包括前边子矩阵，结果肯定是减小的，所以直接舍弃前边子矩阵\n\n参考代码:\n#include\nusing namespace std;\nconst int N = 510;\nint n,m;\nint sum = INT_MIN;     // 答案最初设置一个极小值\nint mp[N][N];\nint main(){\n    cin >> n >> m;\n    for(int i = 1; i <= n; i ++){\n        for(int j = 1; j <= m; j ++){\n            int t;cin >> t;\n            mp[i][j] = mp[i-1][j] + t;        //按列求和\n        }\n    }\n    for(int i = 1; i <= n; i ++){\n        for(int j = i; j <= n; j ++){            // i，j限制子矩阵的行\n            int ans = 0;\n            for(int k = 1; k <= m; k ++){        // k 限制子矩阵的列\n                ans += mp[j][k] - mp[i-1][k];\n                if(ans > sum) sum = ans;\n                if(ans < 0) ans = 0;\n            }\n        }\n    }\n    cout << sum;\n    return 0;\n}\n\n E 正文"}],"1451":[{"aid":"66843","title":"1451题约数倍数选卡片-题解(Java详解-博弈论）","date":"2020-02-23","likes":0,"views":1651,"md":"S 正文\n原题链接：蓝桥杯历届试题-约数倍数选卡片\n\n Server-side output Markdown text\n\n解题思路：**博弈论**——对手的必败态就是我的必胜态。需要注意的是只要某个选择可以导致对手出现必败态，则这个选择就是正确的，可以直接返回；而当我所有选择走了一遍之后，发现并没有返回，即并没有对手的必败态，才可以说明这是我的必败态。\n\n```java\n\nimport java.util.ArrayList;\nimport java.util.Collections;\nimport java.util.Scanner;\n\npublic class Main {\n\tstatic int numCard[] = new int[101];// 下标为代表数字，值为数字出现次数\n\tstatic ArrayList<Integer>[] listA = new ArrayList[101];// 存储每个数的约数倍数\n\tstatic ArrayList<Integer> listB = new ArrayList<Integer>();// 存储可选数\n\n\tpublic static void main(String[] args) {\n\t\tScanner sc = new Scanner(System.in);\n\t\tString s1 = sc.nextLine();\n\t\tString s2 = sc.nextLine();\n\t\tsc.close();\n\t\tString s11[] = s1.split(\"\\\\s+\");// 空格个数不一定是一个，直接用\" \"分隔会错误50%\n\t\tString s22[] = s2.split(\"\\\\s+\");\n\n\t\tfor (int i = 0; i < s11.length; i++) {\n\t\t\tint num = Integer.parseInt(s11[i]);\n\t\t\tnumCard[num] += 1;//记录数字出现次数\n\t\t}\n\t\tfor (int i = 0; i < s22.length; i++) {\n\t\t\tlistB.add(Integer.parseInt(s22[i]));//记录可选数字\n\t\t}\n\t\tCollections.sort(listB);//对可选数字排序，这样有多种可行必胜策略时，只会输出较小数\n\t\tfor (int i = 0; i < 101; i++) {\n\t\t\tlistA[i] = new ArrayList<Integer>();//实例化链表，用于存储数字的约数倍数\n\t\t}\n\n\t\tfor (int i = 1; i < 101; i++) {//遍历1~100\n\t\t\tif (numCard[i] != 0) {//如果该数存在\n\t\t\t\tnumCard[i]--;//查看该数被取走后他的约数倍数是否存在\n\t\t\t\tfor (int j = 1; j < 101; j++) {//如果该数的约数倍数存在\n\t\t\t\t\tif (numCard[j] != 0 && (j % i == 0 || i % j == 0)) {\n\t\t\t\t\t\tlistA[i].add(j);//存入\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tnumCard[i]++;//回溯\n\t\t\t}\n\t\t}\n\n\t\tfor (int i = 0; i < listB.size(); i++) {//遍历可选数\n\t\t\tint num = listB.get(i);\n\t\t\tnumCard[num]--;//取出该数\n\t\t\tboolean result = dfs(num);//让对方选\n\t\t\tnumCard[num]++;//回溯\n\t\t\tif (!result) {//对手必败，即我必胜\n\t\t\t\tSystem.out.println(num);\n\t\t\t\treturn;\n\t\t\t}\n\t\t}\n\t\tSystem.out.println(-1);//执行自此说明我取那一张都不行，必败无疑\n\t}\n\n\tprivate static boolean dfs(int num) {\n\t\t//遍历该数的约数倍数，优先选取较大值，因为100以内大数的约数倍数更少，胜率更高，减少递归层数\n\t\t//如果从i从0开始会超时33%\n\t\tfor (int i = listA[num].size() - 1; i >= 0; i--) {\n\t\t\tint num2 = listA[num].get(i);\n\t\t\tif (numCard[num2] > 0) {//如果该数存在约数倍数\n\t\t\t\tnumCard[num2]--;//取出\n\t\t\t\tboolean result = dfs(num2);//轮到我选(这一步会有多层递归，双方轮流选，直到一方没得选)\n\t\t\t\tnumCard[num2]++;//回溯\n\t\t\t\tif (!result ) {//自己选的时候不存在，也就是我没得选了，对方胜利\n\t\t\t\t\treturn true;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn false;//该数的约数倍数不存在\n\t}\n\n}\n\n```\n\n E 正文"},{"aid":"56706","title":"约数倍数选卡片 （C++代码）递归博弈+优化 在官网已AC","date":"2018-12-16","likes":1,"views":2700,"md":"S 正文\n原题链接：蓝桥杯历届试题-约数倍数选卡片\n\n解题思路:\n\n    基本的博弈都可以用递归来求解，这道题由于想不到有效解法，则用 递归+优化\n    1. 尝试所有走法，把局面交给对手，如果对手的局面是必输，则当前局面必胜；\n    2. 尝试所有走法后，还是赢不了那 当前局面比输\n\n    递归思路：\n    dfs(局面s){\n      尝试走一步s变成s1，把s1交给对手\n         如果存在一个s1局面必输：返回赢了;\n      返回必输;\n    }\n\n    不优化 只有50%成绩\n    优化思路：1.优先当前可选的数字大的卡片（数字越大，则约倍数在100内越少，所以递归的层数就越少）\n                    2.常数优化，递归之前预处理每张卡片的下一次可选卡片集合\n\n注意事项:\n\n    这个C语言网不知为什么代码AC不了一直超时17%，我去蓝桥杯官网提交了两次都600msAC了\n\n  ![](https://blog.dotcpp.com/uploads/20181216/1544960599469145.png)\n参考代码:\n#include <iostream>\n#include <cstdio>\n#include <cstring>\n#include <algorithm>\n#include <vector>\n#include <stack>\n#define _for(i,a,b) for(int i=a;i<b;i++)\n#define _unfor(i,a,b) for(int i=a;i>=b;i--)\n#define mset(a,val,n) for(int i=0;i<n;i++)a[i]=val;\n#define FO freopen(\"out.txt\",\"w\",stdout)\n#define RI(a) scanf(\"%d\",&a)\nusing namespace std;\ntypedef long long LL;\n\nint a[111],b[111],c='A';\nvector<int> G[111];\nint ri(){\n    int x=0;\n    while(!isdigit(c))if((c=getchar())=='\\n')return 0;\n    while(isdigit(c)){x=x*10+c-'0';c=getchar();}\n    return x;\n}\nint dp(int i){\n    if(!a[i])return 0;\n    a[i]--;\n    int len=G[i].size();\n    _for(k,0,len){\n        int j=G[i][k];\n        if((!(i%j)||!(j%i))&&a[j])\n        if(!dp(j)){a[i]++;return 1;}\n    }\n    a[i]++;\n    return 0;\n}\nint main(){\n\n    int x;\n    while(x=ri()){\n        a[x]++;\n        if(c=='\\n')break;\n    }\n    //预处理\n    _for(i,1,101)\n        _unfor(j,100,1)if((!(i%j)||!(j%i))&&a[j])\n            G[i].push_back(j);\n    //\n    while(x=ri()){\n        b[x]++;\n        if(c=='\\n')break;\n    }\n    _for(i,1,101)if(b[i])\n        if(!dp(i)){printf(\"%d\\n\",i);return 0;}\n    printf(\"%d\\n\",-1);\n    return 0;\n}\n\n E 正文"}],"1452":[{"aid":"84484","title":"网络寻路-dfs","date":"2022-02-26","likes":0,"views":902,"md":"S 正文\n原题链接：蓝桥杯历届试题-网络寻路\n\n注意事项:\n保存前继结点的状态。\n\n参考代码:\n#include<iostream>\n#include<cstdio>\n#include<algorithm>\n#include<cmath>\n#include<cstring>\n#include<vector>\n#include<utility>\n#include<map>\nusing namespace std;\nvector<long long> num[10005];\nlong long N,M,u,v,ans;\nvoid dfs(int i,int k,int w){\n\tif(k==3){\n\t\tans++;\n\t\treturn;\n\t}\n\tfor(int j=0;j<num[i].size();j++){\n\t\tif(num[i][j]!=w){\n\n\t\t\tdfs(num[i][j],k+1,i);\n\n\t\t}\n\t}\n}\nint main(){\n\tcin>>N>>M;\n\twhile(M--){\n\t\tscanf(\"%lld%lld\",&u,&v);\n\t\tnum[u].push_back(v);\n\t\tnum[v].push_back(u);\n\t}\n\tfor(int i=1;i<=N;i++){\n\t\tdfs(i,0,-1);\n\t}\n\tcout<<ans<<endl;\n\treturn 0;\n}\n\n E 正文"},{"aid":"83772","title":"dfs求解-网络寻路","date":"2022-02-10","likes":0,"views":802,"md":"S 正文\n原题链接：蓝桥杯历届试题-网络寻路\n\n Server-side output Markdown text\n```cpp\n#include <iostream>\n#include <vector>\nusing namespace std;\nconst int N=1e4+10;\nint n,m,cnt=0;\nvector<int> v[N];\nvoid dfs(int x,int fa,int c){\n  if(c==3){\n    cnt++;\n    return;\n  }\n  for(int i=0;i<v[x].size();i++){\n    int a=v[x][i];\n    if(a!=fa){\n      dfs(a,x,c+1);\n    }\n  }\n}\nint main()\n{\n  cin>>n>>m;\n  for(int i=0;i<m;i++){\n    int x,y;\n    cin>>x>>y;\n    v[x].push_back(y);\n    v[y].push_back(x);\n  }\n  for(int i=1;i<=n;i++){\n    dfs(i,-1,0);\n  }\n  cout<<cnt<<endl;\n  return 0;\n}\n```\n\n E 正文"},{"aid":"82720","title":"网络寻路-通过DFS(深搜)+邻接表实现 [Java][超详细注解]","date":"2022-01-16","likes":0,"views":1757,"md":"S 正文\n原题链接：蓝桥杯历届试题-网络寻路\n\n Server-side output Markdown text\n# 基本思路\n\n首先找路径数，很明显能想到用DFS（深度优先搜索）\n但是有没有明确的终点，同时还给了一共需要转发2次（即需要走四个地点）\n那么我们就可以想到用邻接表或邻接矩阵的数据结构来储存地点之间的线路关系。\n\n## 邻接表的介绍\n\n邻接表就是用一个集合储存多个集合。其中最外部的集合为地点编号、内部的集合表示该地点所能到达的地点。按照样例输入后，邻接表形式如下\n此时我们有一个Vector<Vector<Integer>>\nV1 -> 2 、3、4\nV2 -> 1、3\nV3 -> 1、2\nV4 -> 1\n\n## 深搜的思路\n\n**深搜的结束条件：**\n走到了最后一个点。此时就算是一条成功的转发路线。\n\n**深搜的继续条件：**\n转发次数还没满两次（或者可以理解为走的点还没有满四个）\n那么就继续对当前点可以走到的所有点进行一次遍历，并且判断是否可以走后\n再对下一个点，进行一次DFS搜索。知道满足结束条件后，退出DFS。\n\n## 为什么不用邻接矩阵\n\n邻接矩阵通常适用于稠密图，如果是非稠密图会造成很大的内存浪费，同时会让DFS次数增多，可能会有爆栈的风险，此处不用它，所以不详细讲，如果有兴趣可以自己了解邻接矩阵的数据结构。\n\n# 实现代码\n\n```java\npackage 蓝桥;\n\nimport java.util.*;\n\npublic class 网络寻路_1452 {\n\n    public static Vector<Vector<Integer>> vertexes = new Vector<>();\n\n    public static int[] visited = new int[100001];\n\n    public static int sum = 0;\n\n    public static int start = 0;\n\n    // 题目地址：https://www.dotcpp.com/oj/problem1452.html\n    // 思路：深搜（DFS）、邻接表\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        int n = scanner.nextInt(), m = scanner.nextInt();\n\n        // 初始化邻接表\n        for (int i = 0; i < n; i++) {\n            vertexes.add(new Vector<>());\n        }\n\n        // 邻接表的输入\n        for (int i = 0; i < m; i++) {\n            int from = scanner.nextInt();\n            int to = scanner.nextInt();\n            // 此处我们将输入的第一个点作为出发的点\n            // 那么to就是from这个的目标点\n            vertexes.get(from - 1).add(to - 1);\n            // 此处我们将输入的第二个点作为出发的点\n            // 那么from就是to这个的目标点\n            vertexes.get(to - 1).add(from - 1);\n            // 为什么要这样？！因为这些线路是双向的，可以往回走的！\n        }\n\n        int i = 0;\n        for (Vector<Integer> node : vertexes) {\n            // 先把起点标记上\n            visited[i] = 1;\n            // 记录开始的点，这里start是全局变量，所以在DFS里面也可以访问\n            // 主要用来做到最后到终点的判断\n            start = i;\n            DFS(1, node);\n            // 记得还原\n            visited[i] = 0;\n            // 因为for用了快速遍历，所以需要有一个i记录起点\n            // 当然我们用传统for语句也可以\n            i++;\n        }\n\n        System.out.println(sum);\n    }\n\n    // forwarnNum 用来记录走的地点数量、node用来记录下一个可以走的点的集合\n    public static void DFS(int forwardNum, Vector<Integer> node) {\n        // 如果 forwardNum == 那就说明此时走的就是最后到终点的那一步\n        // 此时我么做一个特殊判断即可，不需要在做一次DFS了。\n        if (forwardNum == 3) {\n            for (int vertex : node) {\n                // 此处有两种可能，走过的下一个点，从来没有被走过，自然可以走\n                // 第二种：和起点一样，则也可以走。\n                // 满足上述两种的话，就 sum++ 并退出\n                if (visited[vertex] == 0 || vertex == start) {\n                    sum++;\n                }\n            }\n            return;\n        }\n\n        // 能到这里，就说嘛不是最后的异步\n        // 就把这点能走的其他点走一遍\n        for (int vertex : node) {\n            // 如果这个点之前已经被记录走过了，那就不走他\n            if (visited[vertex] == 1) continue;\n            // 能到这里就是可以走\n            // 那就接着获取走了之后，能走的点\n            Vector<Integer> next = vertexes.get(vertex);\n            // 标记为已走过\n            visited[vertex] = 1;\n            DFS(forwardNum + 1, next);\n            // 记得还原！\n            visited[vertex] = 0;\n        }\n    }\n}\n\n```\n\n E 正文"},{"aid":"70400","title":"蓝桥杯历届试题-网络寻路-题解（C++代码）","date":"2020-05-26","likes":0,"views":1441,"md":"S 正文\n原题链接：蓝桥杯历届试题-网络寻路\n\n Server-side output Markdown text\n题目 1452: [蓝桥杯][历届试题]网络寻路\n\n时间限制: 1Sec 内存限制: 128MB 提交: 308 解决: 129\n\n题目描述\nX  国的一个网络使用若干条线路连接若干个节点。节点间的通信是双向的。某重要数据包，为了安全起见，必须恰好被转发两次到达目的地。该包可能在任意一个节点产生，我们需要知道该网络中一共有多少种不同的转发路径。\n源地址和目标地址可以相同，但中间节点必须不同。\n如下图所示的网络。\n\n1  ->   2  ->   3  ->   1  是允许的\n1  ->   2  ->   1  ->   2  或者  1  ->   2  ->   3  ->   2  都是非法的。\n输入\n输入数据的第一行为两个整数N  M，分别表示节点个数和连接线路的条数(1< =N< =10000;  0< =M< =100000)。\n接下去有M行，每行为两个整数  u  和  v，表示节点u  和  v  联通(1< =u,v< =N  ,  u!=v)。\n输入数据保证任意两点最多只有一条边连接，并且没有自己连自己的边，即不存在重边和自环。\n输出\n输出一个整数，表示满足要求的路径条数。\n样例输入\n4 4\n1 2\n2 3\n3 1\n1 4\n样例输出\n10\n\n```cpp\n//网络寻路！大数节点图，临界矩阵不行\n//只能采取邻接表，这里采用 链式向前星 和 dfs来尝试解决此题\n#include <iostream>\n#include <cstring>\n#include <algorithm>\nusing namespace std;\nint n,m;\nstruct node{\n\tint u;\n\tint v;\n\tint front;\n}edge[200005];\nbool vis[10005];\nint head[10005];\nint cnt = 0;\nlong long sum =0;\nvoid add(int u,int v)\n{\n\tedge[cnt].u = u;\n\tedge[cnt].v = v;\n\tedge[cnt].front = head[u];\n\thead [u] = cnt++;\n\n\tedge[cnt].u = v;\n\tedge[cnt].v = u;\n\tedge[cnt].front = head[v];\n\thead [v] = cnt++;\n}\n\nvoid dfs(int u,int v,int step)\n{\n\tif(step==2)\n\t{\n\t\tfor(int i =head[v];i!=-1;i=edge[i].front)\n\t\t\tif(vis[edge[i].v]==false||edge[i].v==u) sum++;\n\n\t\treturn ;\n\t}\n\tfor(int i =head[v];i!=-1;i=edge[i].front)\n\t{\n\t\tif(vis[edge[i].v]==false)\n\t\t{\n\t\t\tvis[v] =true;\n\t\t\tdfs(u,edge[i].v,step+1);\n\t\t\tvis[v] =false;\n\t\t}\n\t}\n\treturn ;\n}\nint main()\n{\n\tcin>>n>>m;\n\tmemset(head,-1,sizeof(head));\n\tmemset(vis,false,sizeof(vis));\n\tfor(int i =0;i<m;i++)\n\t{\n\t\tint u,v;\n\t\tcin>>u>>v;\n\t\tadd(u,v);\n\t}\n\n\tfor(int i = 1;i<=n;i++)\n\t{\n\t\tvis[i] = true;\n\t\tdfs(i,i,0);\n\t}\n\tcout<<sum<<endl;\n}\n```\n\n E 正文"},{"aid":"65359","title":"蓝桥杯历届试题-网络寻路-题解(Java代码)","date":"2020-02-04","likes":0,"views":1464,"md":"S 正文\n原题链接：蓝桥杯历届试题-网络寻路\n\n Server-side output Markdown text\n    public class Main{\n    \tstatic boolean vis[]=new boolean[10010];//记录走过的节点\n    \tstatic ArrayList<ArrayList<Integer>> map=new ArrayList<ArrayList<Integer>>();//邻接表\n    \tstatic int ans=0;\n    \tpublic static void main(String[] args) {\n    \t\tScanner input=new Scanner(System.in);\n    \t\tint n=input.nextInt();\n    \t\tint m=input.nextInt();\n    \t\tfor(int i=0;i<=n;i++) { //初始化节点,去掉下标为0的节点(置为-1)\n    \t\t\tmap.add(new ArrayList<Integer>());\n    \t\t\tmap.get(i).add(-1);\n    \t\t}\n    \t\tfor(int i=1;i<=m;i++) {\n    \t\t\tint u=input.nextInt();\n    \t\t\tint v=input.nextInt();\n    \t\t\tmap.get(u).add(v);\n    \t\t\tmap.get(v).add(u);\n    \t\t}\n    \t\tArrays.fill(vis, false); //初始化数组vis\n    \t\tfor(int i=1;i<=n;i++) {\n    \t\t\tvis[i]=true;\n    \t\t\tdfs(i,1,i);\n    \t\t\tvis[i]=false;\n    \t\t}\n    \tSystem.out.println(ans);\n    \t}\n    \tstatic void dfs(int cur,int step,int root) { //cur：当前节点，step：节点数，root:第一个节点\n    \t\tif(step==3) {  //当节点数正好为3时\n    \t\t\tfor(int i=1;i<map.get(cur).size();i++) {\n    \t\t\t\tif(!vis[map.get(cur).get(i)]||map.get(cur).get(i)==root) {  //判断第四个节点是否为第一个节点或者是没有走过的节点\n    \t\t\t\t\tans++;\n    \t\t\t\t}\n    \t\t\t}\n    \t\t}else{\n    \t\t\tfor(int i=1;i<map.get(cur).size();i++) {\n    \t\t\t\tif(!vis[map.get(cur).get(i)]) {\n    \t\t\t\t\tvis[map.get(cur).get(i)]=true;\n    \t\t\t\t\tdfs(map.get(cur).get(i),step+1,root);\n    \t\t\t\t\tvis[map.get(cur).get(i)]=false;\n    \t\t\t\t}\n    \t\t\t}\n    \t\t}\n    \t}\n    }\n\n E 正文"}],"1453":[{"aid":"110209","title":"蓝桥杯历届试题-翻硬币","date":"2026-03-05","likes":1,"views":279,"md":"S 正文\n原题链接：蓝桥杯历届试题-翻硬币\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include <bits/stdc++.h>\nusing namespace std;\n\nint main(){\n\tstring s1,s2;\n\tcin>>s1>>s2;\n\tint len=s1.size();\n\tint re=0;\n\tfor(int i=0;i<len-1;i++)\n\t{\n\t\tif(s1[i]!=s2[i]){\n\t\t\tif(s1[i]=='*') s1[i]='o';\n\t\t\telse s1[i]='*';\n\n\t\t\tif(s1[i+1]=='*') s1[i+1]='o';\n\t\t\telse s1[i+1]='*';\n\t\t\tre++;\n\t\t}\n\t}\n\tcout<<re;\n\treturn 0;\n}\n\n E 正文"},{"aid":"107349","title":"超简单思路+代码 # 1453: 蓝桥杯历届试题-翻硬币 (C++)","date":"2024-11-22","likes":0,"views":696,"md":"S 正文\n原题链接：蓝桥杯历届试题-翻硬币\n\n Server-side output Markdown text\n- 思路:遍历每个位置,只要当前位置不一样就翻一次,最终得到的答案就是最优解\n\n```c++\n#define _CRT_SECURE_NO_WARNINGS 1\n#include<algorithm>\n#include<iostream>\n#include<sstream>\n#include<cstring>\n#include<cstdio>\n#include<cmath>\n#include<string>\n#include<vector>\n#include<stack>\n#include<queue>\n#include<map>\n#include<set>\n#define MAX 0x3f3f3f3f\n#define MIN -0x3f3f3f3f\nusing namespace std;\ntypedef long long ll;\n\nstring s1, s2;\n\nvoid turn(int i) {\n\tif (s1[i] == '*')s1[i] = 'o';\n\telse s1[i] = '*';\n}\n\nint main() {\n\tint res = 0;\n\n\tcin >> s1 >> s2;\n\n\tfor (int i = 0; i < s1.size(); i++) {\n\t\tif (s1[i] != s2[i]) {\n\t\t\tturn(i), turn(i + 1);\n\t\t\tres++;\n\t\t}\n\t}\n\n\tcout << res;\n\n\treturn 0;\n}\n```\n\n E 正文"},{"aid":"107193","title":"蓝桥杯历届试题-翻硬币，这真的是比赛题吗？","date":"2024-11-16","likes":0,"views":557,"md":"S 正文\n原题链接：蓝桥杯历届试题-翻硬币\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include\"bits/stdc++.h\"\nusing namespace std;\nint main(){\n    // 定义两个字符串变量s1和s2，用于存储输入的字符串\n    string s1, s2;\n    // 定义一个整数变量num，并初始化为0，用于记录不同字符对的数量\n    int num = 0;\n    // 从标准输入读取两个字符串s1和s2\n    cin >> s1 >> s2;\n    // 获取字符串s1的长度\n    int l1 = s1.size();\n    // 遍历字符串s1的每一个字符\n    for(int i = 0; i < l1; i++){\n        // 如果s1和s2在当前位置的字符不同\n        if(s1[i] != s2[i]){\n            // 从当前位置的下一个字符开始继续遍历\n            for(int j = i + 1; j < l1; j++){\n                // 如果找到另一个不同的字符对\n                if(s1[j] != s2[j]){\n                    // 计算两个不同字符之间的距离，并累加到num中\n                    num += (j - i);\n                    // 更新外层循环的索引i为当前找到的不同字符的位置\n                    i = j;\n                    // 跳出内层循环\n                    break;\n                }\n            }\n        }\n    }\n    // 输出最终计算出的不同字符对的数量\n    cout << num << endl;\n    return 0;\n}\n\n E 正文"},{"aid":"104367","title":"蓝桥杯历届试题-翻硬币（贪心）","date":"2024-04-12","likes":0,"views":617,"md":"S 正文\n原题链接：蓝桥杯历届试题-翻硬币\n\n#include <iostream>\n#include <cstring>\nusing namespace std;\n\nconst int N = 110;\n\nint n;\nchar s1[N], s2[N];\n\nvoid turn(int i)\n{\n    if (s1[i] == '*') s1[i] = 'o';\n    else s1[i] = '*';\n}\n\nint main()\n{\n    cin >> s1 >> s2;\n\n    n = strlen(s1);\n\n    int res = 0;\n    for (int i = 0; i < n; i ++ )\n        if (s1[i] != s2[i])\n        {\n            turn(i), turn(i + 1);\n            res ++ ;\n        }\n\n    cout << res << endl;\n}解题思路:\n\n注意事项:\n\n参考代码:\n\n E 正文"},{"aid":"104097","title":"蓝桥杯历届试题-翻硬币","date":"2024-04-02","likes":0,"views":483,"md":"S 正文\n原题链接：蓝桥杯历届试题-翻硬币\n\n参考代码:\n#include<bits/stdc++.h>\nusing namespace std;\nvector<int>v;\nint main()\n{\n\tstring s,ss;\n\tcin>>s>>ss;\n\tint len=s.length();\n\tfor(int i=0;i<len;i++)\n\t{\n\t\tif(s[i]!=ss[i])\n\t\t{\n\t\t\tv.push_back(i);\n\t\t}\n\t}\n\tint ans=0;\n\tfor(int i=0;i<v.size();i++)\n\t{\n\t\tif(i%2==0)\n\t\t{\n\t\t\tans+=v[i+1]-v[i];\n\t\t}\n\t}\n\tcout<<ans;\n\treturn 0;\n}\n\n E 正文"}],"1454":[{"aid":"108386","title":"来自一个肺雾的参考评论各处后的理解","date":"2025-02-04","likes":1,"views":735,"md":"S 正文\n原题链接：蓝桥杯历届试题-蚂蚁感冒\n\n解题思路:我一直在纠结这些蚂蚁出发的位置，纠结他们是否会相遇，其实是从最左端看起，当初始位置是负数时，头向左，两种情况可以感染蚂蚁，一种感染绝对值小于初始蚂蚁的同时头向右的蚂蚁，一种是绝对值大于初始蚂蚁同时头向左。正数时同理。之前一直不理解为啥绝对值要进行对比，现在也是一知半解，因为有特殊情况一只蚂蚁也感染不了，没有任何一只蚂蚁会碰面，进行绝对值的对比，才能判断是否有交织也就是路程能否有碰面\n注意事项:\n\n参考代码:\n#include<bits/stdc++.h>\nusing namespace std;\nint a[101];\nint main ()\n{\n  int ans=1; // 算上感染的第一个\n\tint n=0;\n\tcin>>n;\n\tfor(int i=0;i<n;i++)\n\t{\n\t\tcin>>a[i];\n\t}\n\t//判断初始位置的正负值\nif(a[0]<0){\n\n\tfor(int i=1;i<n;i++){\n\n        if(a[i]>0&&abs(a[i])<abs(a[0])||a[i]<0&&abs(a[i])>fabs(a[0])){\n           ans++;\n        }\n    }\n}\n    if(a[0]>0)\n    {\n\tfor(int i=1;i<n;i++){\n        if(a[i]<0&&abs(a[i])>a[0]||a[i]>0&&a[i]<a[0]){\n            ans++;\n        }\n    }\n}\n\tcout<<ans<<endl;\n\n\treturn 0;\n }\n\n E 正文"},{"aid":"106321","title":"编写题解 1454: 蓝桥杯历届试题-蚂蚁感冒","date":"2024-09-10","likes":0,"views":586,"md":"S 正文\n原题链接：蓝桥杯历届试题-蚂蚁感冒\n\n解题思路:\n\n注意事项:\n\n参考代码:\nimport java.util.Scanner;\n\npublic class Main {\n\tpublic static void main(String[] args) {\n\t\tScanner scanner = new Scanner(System.in);\n\t\tint n = scanner.nextInt();//蚂蚁的总数\n\t\tint[] arr = new int[n];\n\t\tfor (int i = 0; i < arr.length; i++) {\n\t\t\tarr[i] = scanner.nextInt();//蚂蚁离开杆子左边端点的距离\n\t\t}\n\n\t\tboolean flag = false;//判断是否感冒\n\t\tint count = 1;//计数，刚开始只有一只蚂蚁感冒\n\t\tint first = arr[0];//第一只是感冒的蚂蚁\n\t\tfor (int i = 1; i < arr.length; i++) {\n\t\t\tif (first > 0) {//第一只蚂蚁右行\n\t\t\t\t//如果感冒蚂蚁往右走，那么右边左行的蚂蚁会感冒,碰撞后，互相掉头\n\t\t\t\tif ((Math.abs(arr[i]) > first) && arr[i] < 0) {\n\t\t\t\t\tcount++;\n\t\t\t\t\tflag = true;\n\t\t\t\t}\n\t\t\t\t//前提是感冒蚂蚁要掉头后\n\t\t\t\t//掉头后，感冒蚂蚁往左走，那么左边右行的蚂蚁会感冒\n\t\t\t\tif((Math.abs(arr[i]) < first) && arr[i] > 0) {\n\t\t\t\t\tcount++;\n\t\t\t\t}\n\t\t\t}else {//第一只蚂蚁左行\n\t\t\t\t//左行，是负数，第一只蚂蚁要加绝对值\n\t\t\t\t//如果感冒蚂蚁往左走，那么左边右行的蚂蚁会感冒\n\t\t\t\tif ((Math.abs(arr[i]) < Math.abs(first)) && arr[i] > 0) {\n\t\t\t\t\tcount++;\n\t\t\t\t\tflag = true;\n\t\t\t\t}\n\t\t\t\t//前提是感冒蚂蚁要掉头后\n\t\t\t\t//掉头后，感冒蚂蚁往右走，那么右边左行的蚂蚁会感冒\n\t\t\t\tif ((Math.abs(arr[i]) > Math.abs(first)) && arr[i] < 0) {\n\t\t\t\t\tcount++;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\n\t\tif (flag) {\n\t\t\tSystem.out.println(count);\n\t\t}else {\n\t\t\tSystem.out.println(1);\n\t\t}\n\t}\n}\n\n E 正文"},{"aid":"103063","title":"编写题解 1454: 蓝桥杯历届试题-蚂蚁感冒(Java)","date":"2024-03-04","likes":0,"views":572,"md":"S 正文\n原题链接：蓝桥杯历届试题-蚂蚁感冒\n\n Server-side output Markdown text\n写的挺烂,不过能跑完测试用例懒得改了\n```java\n\nimport java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] arr = new int[n];\n        for (int i = 0; i < n; i++) {\n            arr[i] = sc.nextInt();\n        }\n        int count = 1;\n        int t = arr[0];\n        int index = sort(arr);//记录被感染的蚂蚁排序后的索引\n        if (t < 0) {\n            for (int i = 0; i < index; i++) {\n                if (arr[i] > 0) {\n                    count++;\n                }\n            }\n            for (int i = index + 1; i < arr.length; i++) {\n                if (arr[i] < 0) {\n                    count++;\n                }\n            }\n        } else {\n            for (int i = 0; i < arr.length; i++) {\n                if (arr[i] < 0) {\n                    //如果有一个蚂蚁朝着逆行,那么左边的蚂蚁,不是逆行的全部感染\n                    for (int j = 0; j < index; j++) {\n                        if (arr[j] > 0) {\n                            count++;\n                        }\n                    }\n                    break;\n                }\n            }\n            for (int i = index + 1; i < arr.length; i++) {\n                if (arr[i] < 0) {\n                    count++;\n                }\n            }\n        }\n        System.out.println(count);\n    }\n\n    public static int sort(int[] arr) {\n        int t = arr[0];\n\t\t//绝对值排序\n        for (int i = 0; i < arr.length - 1; i++) {\n            if (Math.abs(arr[i]) > Math.abs(arr[i + 1])) {\n                int temp = arr[i + 1];\n                arr[i + 1] = arr[i];\n                arr[i] = temp;\n            }\n        }\n        for (int i = 0; i < arr.length; i++) {\n            if (arr[i] == t) {\n                return i;\n            }\n        }\n        return 0;//没有意义,因为必定能找到\n    }\n\n}\n```\n\n E 正文"},{"aid":"96240","title":"Python‘’蚂蚁感冒‘’，编程即数学（优质题解）","date":"2023-05-02","likes":0,"views":632,"md":"S 正文\n原题链接：蓝桥杯历届试题-蚂蚁感冒\n\n解题思路:\n可以把碰头回头改为交叉带病，完全等价\n\n参考代码:\nn=int(input())\nq=list(map(int,input().split()))\nx=q[0]\nnum=1\nfor i in range(n):\n  for j in range(i,n):\n     if abs(q[i])>abs(q[j]):\n        q[i],q[j]=q[j],q[i]\nfor i in range(n):\n  if q[i]==x:\n     x=i\n     break\nif q[x]>0:\n  for i in range(x+1,n):\n     if q[i]<0:\n        num=num+1\n  if num>=2:\n     for i in range(0,x):\n        if q[i]>0:\n           num=num+1\nelif q[x]<0:\n  for i in range(0,x):\n     if q[i]>0:\n        num=num+1\n  if num>=2:\n     for i in range(x+1,n):\n        if q[i]<0:\n           num=num+1\nprint(num)\n看完记得点个赞\n\n E 正文"},{"aid":"94915","title":"1454: 蓝桥杯历届试题-蚂蚁感冒——纯模拟","date":"2023-03-16","likes":0,"views":686,"md":"S 正文\n原题链接：蓝桥杯历届试题-蚂蚁感冒\n\n Server-side output Markdown text\n    #include<iostream>\n    #include<iomanip>\n    #include<string.h>\n    #include<math.h>\n    #include<cmath>\n    #include<algorithm>\n    #include <bits/stdc++.h>\n\n    using namespace std;\n\n    int main()\n    {\n    \tint n;\n\n    \tcin>>n;\n    \tint a[n][2];\n\n    \tfor(int i=0;i<n;i++){\n    \t\tcin>>a[i][0];\n    \t}\n    \ta[0][1]=1;\n\n    \twhile(true){\n    \t\tfor(int i=0;i<n;i++){\n    \t\t\tif(a[i][0]!=0&&a[i][0]!=100&&a[i][0]!=-100){\n    \t\t\t\ta[i][0]++;\n    \t\t\t}\n    \t\t}\n\n    \t\tfor(int i=0;i<n;i++){\n    \t\t\tif(a[i][0]!=0&&a[i][0]!=100&&a[i][0]!=-100){\n    \t\t\t\tfor(int j=i;j<n;j++){\n    \t\t\t\t\tif(a[j][0]!=0&&a[j][0]!=100&&a[j][0]!=-100){\n    \t\t\t\t\t\tif(abs(a[i][0])==abs(a[j][0])||abs(a[i][0]+a[j][0])==1){\n    \t\t\t\t\t\t\tif(a[i][1]==1||a[j][1]==1){\n    \t\t\t\t\t\t\t\ta[i][1]=1;\n    \t\t\t\t\t\t\t\ta[j][1]=1;\n    \t\t\t\t\t\t\t}\n    \t\t\t\t\t\t}\n    \t\t\t\t\t}\n    \t\t\t\t}\n    \t\t\t}\n\n    \t\t}\n\n    \t\tbool flag=true;\n\n    \t\tfor(int i=0;i<n;i++){\n    \t\t\tif(a[i][0]!=0&&a[i][0]!=100&&a[i][0]!=-100){\n    \t\t\t\tflag=false;\n    \t\t\t}\n    \t\t}\n\n    \t\tif(flag){\n    \t\t\tbreak;\n    \t\t}\n\n    \t}\n\n    \tint count=0;\n\n    \tfor(int i=0;i<n;i++){\n    \t\tif(a[i][1]==1){\n    \t\t\t++count;\n    \t\t}\n\n    \t}\n\n    \tcout<<count;\n\n        return 0;\n    }\n\n E 正文"}],"1455":[{"aid":"66896","title":"蓝桥杯历届试题-车轮轴迹-题解(C++代码)","date":"2020-02-24","likes":0,"views":2256,"md":"S 正文\n原题链接：蓝桥杯历届试题-车轮轴迹\n\n Server-side output Markdown text\n请参考\n```cpp\n#include <iostream>\n#include <cstdlib>\n#include <cstdio>\n#include <cstring>\n#include <vector>\n#include <cmath>\n#include <algorithm>\n\nusing namespace std;\n\nconst int MAXN = 10000;\nconst double PI = atan(1.0) * 4;\nconst double EPS = 1e-10;\n\nclass Point {\npublic:\n    double x, y;\n    Point() {}\n    Point(double x, double y) : x(x), y(y) {}\n    Point operator - (const Point &r) const { return Point(x-r.x, y-r.y); }\n    Point operator + (const Point &r) const { return Point(x+r.x, y+r.y); }\n    Point &operator += (const Point &r) { x += r.x; y += r.y; return *this; }\n    Point &operator *= (double m) { x *= m; y *= m; return *this; }\n    Point pOfRotate(double angle) const {\n        double cosA = cos(angle);\n        double sinA = sin(angle);\n        return Point(cosA*x-sinA*y, sinA*x+cosA*y);\n    }\n    Point pOfRotate90() const { return Point(-y, x); }\n    double length() const { return sqrt(x*x+y*y); }\n    Point pOfNormal() const {\n        double len = length();\n        return Point(x/len, y/len);\n    }\n    double angle() const { return atan2(y, x); }\n};\n\nostream & operator <<(ostream &os, const Point &v)\n{\n    os << \"(\" << v.x << \",\" << v.y << \")\";\n    return os;\n}\n\nclass Segment;\nclass Circle;\n\nclass Seg {\npublic:\n    virtual double getLeft() const = 0;\n    virtual double getRight() const = 0;\n    virtual double getY(double x) const = 0;\n    virtual double getLength(double x1, double x2) const = 0;\n    virtual void intersect(Seg *r) const = 0;\n    virtual void intersect(const Segment &v) const = 0;\n    virtual void intersect(const Circle &v) const = 0;\n    bool contains(double x) const { return x>=getLeft() && x<=getRight(); }\n    virtual void acceptPrint(ostream &os) const = 0;\n};\n\nostream & operator <<(ostream &os, const Seg &v)\n{\n    v.acceptPrint(os);\n    return os;\n}\n\nPoint intersectRet[4];\nint tIntersectRet;\n\nclass Segment : public Seg {\npublic:\n    Point a, b;\n    Segment &moveLeft(double dis)\n    {\n        Point tmp = ((b-a).pOfRotate90().pOfNormal() *= dis);\n        a += tmp;\n        b += tmp;\n        return *this;\n    }\n    virtual double getLeft() const { return a.x; }\n    virtual double getRight() const { return b.x; }\n    virtual double getY(double x) const {\n        return (x-a.x)*(b.y-a.y)/(b.x-a.x)+a.y;\n    }\n    virtual double getLength(double x1, double x2) const {\n        return (x2-x1) * (b-a).length() / (b.x-a.x);\n    }\n    virtual void intersect(Seg *r) const {\n        r->intersect(*this);\n    }\n    virtual void intersect(const Segment &v) const {\n        tIntersectRet = 0;\n        double ang = (b-a).angle();\n        Point c = (v.a-a).pOfRotate(-ang);\n        Point d = (v.b-a).pOfRotate(-ang);\n        // Bug\n        //double di = b.length();\n        double di = (b-a).length();\n        if (!((c.y>0&&d.y<0) || (c.y<0&&d.y>0)))\n            return ;\n        double x = (d.x-c.x) * (-c.y) / (d.y-c.y) + c.x;\n        if (x<0 || x>di)\n            return ;\n        Point ret = Point(x,0).pOfRotate(ang)+a;\n        intersectRet[tIntersectRet++] = ret;\n    }\n    virtual void intersect(const Circle &v) const;\n    virtual void acceptPrint(ostream &os) const {\n        os << a << \"-\" << b;\n    }\n};\n\nclass Circle : public Seg {\npublic:\n    Point c;\n    double r;\n    virtual double getLeft() const { return c.x - r; }\n    virtual double getRight() const { return c.x + r; }\n    virtual double getY(double x) const {\n        double y2 = r * r - (c.x - x) * (c.x - x);\n        if (y2<0) y2 = 0;\n        return c.y + sqrt(y2);\n    }\n    virtual double getLength(double x1, double x2) const {\n        x1 -= c.x; x2 -= c.x;\n        double a1 = Point(x1, sqrt(abs(r*r-x1*x1))).angle(), a2 = Point(x2, sqrt(abs(r*r-x2*x2))).angle();\n        return (a1-a2) * r;\n    }\n    virtual void intersect(Seg *r) const {\n        r->intersect(*this);\n    }\n    virtual void intersect(const Segment &v) const {\n        tIntersectRet = 0;\n        Point a = v.a - c;\n        Point b = v.b - c;\n\n（正文过长，已截断，全文见原文链接）"}],"1456":[{"aid":"103214","title":"蓝桥杯历届试题-连号区间数","date":"2024-03-09","likes":0,"views":986,"md":"S 正文\n原题链接：蓝桥杯历届试题-连号区间数\n\n暴力思路：\n    首先这个题需要理解这个连续性是什么，比如给你一个数组：1 3 5 4 2，然后我在里面随便去一段（取3 5 4）然后我把它排序（从小到大）发现也是3，4，5        那   就说明是连续的，除此之外当l=r时也算作连续\n    分别枚举区间的左端点和右端点，对左右端点区间进行sort排序，判断是否连续\n   暴力做法时间复杂度O(n^3logn)大于O(n^2)，所以只能过一部分的数据，但能得一部分得分数\n#include <iostream>\n#include <cstring>\n#include <cstdio>\n#include <algorithm>\n\nusing namespace std;\nusing ll=long long;\n\nconst int N=5e4+10;\n\nint a[N],bac[N];\nint res;\nint main()\n{\n  ios::sync_with_stdio(0),cin.tie(0),cout.tie(0);\n  int n;\n  cin>>n;\n  for(int i=1;i<=n;i++)\n  {\n    cin>>a[i];\n  }\n  for(int i=1;i<=n;i++)//枚举左右端点i，j，判断是否连续\n  {\n    for(int j=i;j<=n;j++)\n    {\n      memcpy(bac,a,sizeof a);// 这里要把数组的初始状态存在bac数组中，因为每次sort排序后，数组的顺序会发生改变。\n      sort(a+i,a+j+1);\n      bool flag=true;\n      for(int k=i;k<j;k++)\n      {\n        if(a[k+1]-a[k]>1)\n        {\n          flag=false;\n          break;\n        }\n      }\n      if(flag)res++;\n      memcpy(a,bac,sizeof bac);// 还原数组a的初始状态\n    }\n  }\n  cout<<res;\n  return 0;\n}对暴力做法进行优化，我们假设区间[a,b],则在区间[a,b]之间一共有b-a+1个数，由此说明在区间[a,b]中的\n最大值和最小值之间就相差了b-a。\n#include <iostream>\n#include <cstring>\n#include <cstdio>\n#include <algorithm>\n\nusing namespace std;\n\n// 定义常量N为5e4+10（50010），作为数组大小的上限。定义常量INF为1e8（100000000），用作无穷大的值。\nconst int N = 5e4 + 10, INF = 1e8;\n\nint a[N], bac[N]; // 定义数组a用来存储输入的序列，bac数组定义了但未在代码中使用\nint res; // 定义变量res用来统计满足条件的子序列数量\n\nint main() {\n// 加速输入输出。禁用C与C++的同步以及手动绑定cin与cout\nios::sync_with_stdio(0), cin.tie(0), cout.tie(0);\n\nint n; // 定义n用来接收序列的长度\ncin >> n; // 输入序列的长度n\nfor (int i = 1; i <= n; i++) {\ncin >> a[i]; // 循环接收序列的每个值\n}\n\n// 双重循环检查所有的(i, j)对，其中i为子序列的起始位置，j为子序列的结束位置\nfor (int i = 1; i <= n; i++) {\nint maxb = -INF, mina = INF; // 初始化当前子序列的最大值和最小值\nfor (int j = i; j <= n; j++) {\nmaxb = max(maxb, a[j]); // 更新当前子序列的最大值\nmina = min(mina, a[j]); // 更新当前子序列的最小值\n// 如果当前子序列的最大值与最小值之差等于子序列的长度差，则找到了一个符合条件的子序列\nif (maxb - mina == j - i) res++;\n}\n}\ncout << res; // 输出满足条件的子序列总数\nreturn 0;\n}\n\n E 正文"},{"aid":"86252","title":"最大值最小值解连号区间","date":"2022-04-05","likes":0,"views":1057,"md":"S 正文\n原题链接：蓝桥杯历届试题-连号区间数\n\n Server-side output Markdown text\n### 注意事项\n- 这些数是1到N（没有用）\n- 区间[L,  R]  里的所有元素（即此排列的第L个到第R个元素）递增排序后能得到一个长度为R-L+1的“连续”数列，则称这个区间连号区间。\n注意，是先确定区间再排序，而不是先排序再确定区间\n- 看样例你会发现,区间左端点等于区间右端点也算一个区间\n### 思路分析\n枚举区间，再来检查一下这个区间的数是否符合要求，\n①. 这个检查最暴力的做法是：\n把这个区间的数sort一下，之后判断是否是连续的（下一个数减上一个数为1）；\n②.取巧的方法是先确定这个区间的max和min,max-min是否等于这个区间右端点减去左端点的值来判断是否是连续的\n为什么能利用max-min来判断呢\n假如max为5，min为1，max-min=4\n假设他左端点为1，右端点为5，满足max-min=左端点-右端点\n由于从1到5所有数是小于等于5，大于等于1，且每个数是整数\n所以其他数必定是234\n所以满足max-min等于这个区间右端点减去左端点的值，那么这个区间必定是连号区间，（只能保证这个区间由连续的数组成，无法保证这个区间的数是从小到大或从大到小连续的）\n\n### 参考代码\n\n```java\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.util.StringTokenizer;\n\npublic class Main {\n\tstatic BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));\n\tstatic StringTokenizer stringTokenizer = new StringTokenizer(\"\");\n\n\tstatic String nextLine() throws IOException {\n\t\treturn bufferedReader.readLine();\n\t}\n\n\tstatic String next() throws IOException {\n\t\twhile (!stringTokenizer.hasMoreTokens()) {\n\t\t\tstringTokenizer = new StringTokenizer(bufferedReader.readLine());\n\t\t}\n\t\treturn stringTokenizer.nextToken();\n\t}\n\n\tstatic int nextInt() throws NumberFormatException, IOException {\n\t\treturn Integer.parseInt(next());\n\t}\n\n\tpublic static void main(String[] args) throws NumberFormatException, IOException {\n\t\tint n = nextInt();\n\t\tint arr[] = new int[n];\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tarr[i] = nextInt();\n\t\t}\n\t\tint count = 0;\n\t\t// 枚举区间\n\t\tfor (int i = 0; i < arr.length; i++) {\n\t\t\tint min = Integer.MAX_VALUE;\n\t\t\tint max = Integer.MIN_VALUE;\n\t\t\tfor (int j = i; j < arr.length; j++) {\n\t\t\t\tmin = Math.min(min, arr[j]);\n\t\t\t\tmax = Math.max(max, arr[j]);\n\t\t\t\tif (max - min == j - i) {\n\t\t\t\t\tcount++;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tSystem.out.println(count);\n\t}\n}\n```\n\n E 正文"},{"aid":"85466","title":"最简单枚举（c++）","date":"2022-03-19","likes":0,"views":1000,"md":"S 正文\n原题链接：蓝桥杯历届试题-连号区间数\n\n Server-side output Markdown text\n## 解释：\n3241  符合条件吧，最大值为4，最小值为1，4 - 1 = 3（总共的数-1）\n354  再来一个：最大值为5，最小值未3， 5 - 3 = 2（总共的数-1）\n\n## 代码：\n\n```cpp\n#include<bits/stdc++.h>\n\nusing namespace std;\n\nconst int N = 10000 + 10;\n\nint arr[N];\n\nint n, sum = 0;\n\nint main(){\n    cin >> n;\n    for(int i = 0; i < n; i++)cin >> arr[i];\n\n    for(int i = 0; i < n; i++){\n        int max_num = -N, min_num = N, j;\n        for(j = i; j < n; j++){\n            max_num = max(max_num, arr[j]);\n            min_num = min(min_num, arr[j]);\n            if(max_num - min_num == j - i)sum++;  //最大值 - 最小值 == j - i 个数（总数为j-i+1）\n        }\n\n    }\n\n   cout << sum ;\n\n    return 0;\n}\n```\n\n E 正文"},{"aid":"84481","title":"1456: 蓝桥杯历届试题-连号区间数","date":"2022-02-26","likes":0,"views":704,"md":"S 正文\n原题链接：蓝桥杯历届试题-连号区间数\n\n Server-side output Markdown text\n超时做法\nfor（int i=0;i<n;i++）\n\t  \tfor(int j=i;j<n;j++)\n\t\t{\nsort(i,j)\nflag=true;\nfor(inr k=1;k<i+j-1;k++)\nif(  a[k]-a[k-1]!=1)\nflag=flase,break;\nif(flag)res++;\n\t\t}\n优化后\na1 a2 a3 a4 a5 a6\n 5  6  10 8 9 7\n 6-1+1=10-5+1\n 即区间[a,b]中b-a=max-min\n ```cpp\n#include<iostream>\n#include<cstdio>\n#include<algorithm>\nusing namespace std;\nconst int N=50005;\nint p[N],n,maxn,minn;\nint main()\n{\n\tcin>>n;\n\tfor(int i=0;i<n;i++)cin>>p[i];\n\tint res=0;\n\tfor(int i=0;i<n;i++)\n\t{\n\t\tmaxn=-1e8,minn=1e8;\n\t\tfor(int j=i;j<n;j++)\n\t\t{\n\t\t\tmaxn=max(maxn,p[j]);\n\t\t\tminn=min(minn,p[j]);\n\t\t\tif(maxn-minn==j-i)\n\t\t\tres++;\n\t\t}\n\t}\n\tcout<<res<<endl;\n\n\treturn 0;\n }\n```\n\n E 正文"},{"aid":"84064","title":"python-连号区间数","date":"2022-02-15","likes":0,"views":771,"md":"S 正文\n原题链接：蓝桥杯历届试题-连号区间数\n\n解题思路:\n建立两层循环。第一层循环为l，第二层循环为r。\n每次更新区间[l,r]的最小值和最大值。如果（最大值-最小值）= （r-l）,则连续区间数量加1。\n\n注意事项:\n\n参考代码:\ndef f(n):\n    A = tuple(int(i) for i in input().strip().split())\n    ans = 0\n    for i in range(n):\n        min_num = A[i]\n        max_num = A[i]\n        for j in range(i,n):\n            temp = A[j]\n            if temp > max_num:\n                max_num = temp\n            if temp < min_num:\n                min_num = temp\n            if max_num - min_num +1 == j-i+1:\n                ans = ans+1\n    print(ans)\nif __name__ == '__main__':\n    n = int(input())\n    f(n)\n\n E 正文"}],"1457":[{"aid":"85710","title":"1457: 蓝桥杯历届试题-邮局(JAVA题解)","date":"2022-03-25","likes":0,"views":1277,"md":"S 正文\n原题链接：蓝桥杯历届试题-邮局\n\n解题思路:记忆化dfs\n\n注意事项:\n暴力杯常见的基础搜索题。。一开始在邮局对象内部缓存村民家的位置，被递归内部引用传递绕晕了。。。回头换用一个map数组存储此状态下距离各村民最近的邮局，递归过程中注意状态回溯，本题还可以剪枝来进一步减少时间复杂度。还利用了mem数组存储距离缓存，注意初始化各元素为负数或无穷大。\n\n参考代码:\nimport java.io.*;\nimport java.util.*;\n\npublic class Main {\n    public static class Person{\n        int x, y;\n        Person(int x, int y) {\n            this.x = x;\n            this.y = y;\n        }\n    }\n    public static class Station{\n        int rank;\n        int x, y;\n        Station(int x, int y, int rank) {\n            this.x = x;\n            this.y = y;\n            this.rank = rank;\n        }\n        public double getIns(Person other){\n            return Math.sqrt((this.x-other.x) * (this.x-other.x) + (this.y-other.y) * (this.y-other.y));\n        }\n    }\n\n    static StreamTokenizer cin;\n    static PrintWriter out;\n    static int n;  // 户数\n    static Person[] arr;\n    static int m;  // 备选邮局数\n    static Station[] stations;\n    static int k;  // 要建邮局数\n    static double min_value = Integer.MAX_VALUE;\n    static int[] targets;\n    static double[][] mem;  // 距离缓存\n    public static void main(String[] args) throws IOException{\n        cin = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));\n        out = new PrintWriter(new OutputStreamWriter(System.out));\n        n = nextInt();\n        m = nextInt();\n        k = nextInt();\n        arr = new Person[n+1];\n        stations = new Station[m+1];\n        targets = new int[k];\n        for(int i = 1; i < n+1; i++){\n            arr[i] = new Person(nextInt(), nextInt());\n        }\n        for(int i = 1; i < m+1; i++){\n            stations[i] = new Station(nextInt(), nextInt(), i);\n        }\n        mem = new double[n+1][m+1];\n        for(int i = 1; i < n+1; i++)\n            Arrays.fill(mem[i], -1);\n        dfs(0.0, 1, new LinkedList<>(), new int[n+1]);\n        TreeSet<Integer> set = new TreeSet<>();\n        for(int i = 1;i < n+1; i++)\n            set.add(targets[i]);\n        for(int target : set)\n            out.print(target + \" \");\n        out.flush();\n\n    }\n    static void dfs(double sum, int index, LinkedList<Station> al, int[] map){\n        if(al.size() == k){  // 邮局已选择至上限\n            if(min_value > sum){\n                min_value = sum;\n                targets = map;\n            }\n            return;\n        }\n        if(index == m+1)  // 已经没有可选的邮局, 表明本次选择失败\n            return;\n        // 不选index邮局\n        int[] newMap = new int[n+1];\n        System.arraycopy(map, 1, newMap, 1, n);\n        dfs(sum, index+1, al, newMap);\n        // 选择index邮局\n        // 更新sum\n        Station station = stations[index];  // 待选邮局\n        if(al.isEmpty()){  // 第一个选择的邮局, 更新一个初始值sum\n            for(int i = 1; i < n+1; i++){  // 遍历村民家\n                double dis = station.getIns(arr[i]);\n                map[i] = index;\n                mem[i][index] = dis;\n                sum += dis;\n            }\n        }else{\n            for(int j = 1; j < n+1; j++){\n                Person p = arr[j];\n                double tm = mem[j][map[j]];\n                double nm;\n                if(mem[j][index] != -1)\n                    nm =  mem[j][index];\n                else{\n                    nm = station.getIns(p);\n                    mem[j][index] = nm;\n                }\n                if(nm < tm) { // 更新\n                    sum -= tm;\n                    sum += nm;\n                    map[j] = station.rank;\n                }\n            }\n        }\n        al.add(station);\n        newMap = new int[n+1];\n        System.arraycopy(map, 1, newMap, 1, n);\n        dfs(sum, index+1, al, newMap);\n        al.removeLast();  // 状态回退\n    }\n    static int nextInt() throws IOException{\n        cin.nextToken();\n        return (int)cin.nval;\n    }\n}\n\n E 正文"},{"aid":"66900","title":"蓝桥杯历届试题-邮局-题解(C++代码)","date":"2020-02-24","likes":1,"views":2410,"md":"S 正文\n原题链接：蓝桥杯历届试题-邮局\n\n Server-side output Markdown text\n请参考\n```cpp\n#include <bits/stdc++.h>\nusing namespace std;\n\nconst double inf = 1.7e300;\n\nstruct node\n{\n\tint x, y;\n}point[100], post[100];\n\ndouble mp[101][101];\nint flag[100];\nint n, m, k;\ndouble res = inf;\nint cur[100];\nint ans[100];\n\ndouble dis(node a, node b)\n{\n\treturn sqrt((a.x-b.x)*(a.x-b.x) + (a.y-b.y)*(a.y-b.y));\n}\n\nvoid dfs(int st, int sum_k, double sum_r, double tmp_r[])\n{\n\tif((k - (sum_k-1)) > (m - (st-1))) return ;//剪枝 1\n\tif(st > m && sum_k <= k) return ; //剪枝 2\n\tif(sum_k > k+1) return ;\n\t//cout << st-1 << \" \" <<  sum_k-1 << \" \" << sum_r << endl;\n\tif(sum_k == k+1)\n\t{\n\t\t//cout <<\" shuchu\" << st-1 << \" \" << sum_k-1 << \" \" << sum_r << endl;\n\t\tif(res > sum_r)\n\t\t{\n\t\t\tres = sum_r;\n\t\t\tfor(int i = 1; i <= k; i++)\n\t\t\t{\n\t\t\t\tans[i] = cur[i];\n\t\t\t}\n\t\t\t//cout << \"   \" << res << endl;\n\t\t}\n\t\treturn ;\n\t}\n    double dis_r[55];\n    for(int i = 1; i <= n; i++)\n    {\n        dis_r[i] = tmp_r[i];//必须重新定义一个数组才属于这个函数\n    }\n\n\tdfs(st+1, sum_k, sum_r, dis_r);//不建造此邮局\n\n    if(flag[st] == 1) return ;\n\tcur[sum_k] = st;\n\tint mark1 = 0, mark2 = 0;\n\tif(sum_k == 1)//第一个邮局，初始化 dis_r\n\t{\n\t\tfor(int i = 1; i <= n; i++)\n\t\t{\n\t\t\tdis_r[i] = mp[i][st];\n\t\t\tsum_r += mp[i][st];\n\t\t }\n\t\t mark1 = 1;\n\t}\n\telse\n\t{\n\t\tfor(int i = 1; i <= n; i++)\n\t\t{\n\t\t\tif(dis_r[i] > mp[i][st])\n\t\t\t{\n\t\t\t\tmark2 = 1;\n\t\t\t\tsum_r += mp[i][st] - dis_r[i];\n\t\t\t\tdis_r[i] = mp[i][st];\n\t\t\t}\n\t\t }\n\t}\n    if(mark1==0&&mark2==0) flag[st] = 1;\n\tif(mark1 == 1 || mark2 == 1) dfs(st+1, sum_k+1, sum_r, dis_r);\n\treturn ;\n}\n\nvoid init()\n{\n    for(int i = 1; i <= n; i++)\n\t{\n\t\tscanf(\"%d %d\", &point[i].x, &point[i].y);\n\t}\n\n\tfor(int i = 1; i <= m; i++)\n\t{\n\t\tscanf(\"%d %d\", &post[i].x, &post[i].y);\n\t}\n\n\tfor(int i = 1; i <= n; i++)\n\t{\n\t\tfor(int j = 1; j <= m; j++)\n\t\t{\n\t\t\tmp[i][j] = dis(point[i], post[j]);\n\t\t}\n\t}\n}\n\nint main()\n{\n\tscanf(\"%d %d %d\", &n, &m, &k);\n    init();\n\tdouble dis_r[55];\n\tmemset(dis_r, -1, sizeof(dis_r));\n\tdfs(1, 1, 0, dis_r);\n\tfor(int i = 1; i <= k; i++)\n\t{\n\t\tcout << ans[i] << \" \" ;\n\t}\n\n\treturn 0;\n }\n```\n\n E 正文"},{"aid":"7228","title":"蓝桥杯历届试题-邮局 （C++代码）（时间超限）","date":"2018-04-18","likes":0,"views":2958,"md":"S 正文\n原题链接：蓝桥杯历届试题-邮局\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include<iostream>\n#include<stdlib.h>\n#include<math.h>\nusing namespace std;\nint n,m,k,j,c[55][2],y[27][2],d[12],f1,f2,f[55];\nfloat yc[27][55],s=1000000000;\nint dfs(int t,int i,int o[12],float w[55],float sum)\n{\n\tif(i<=m+1)\n\t{\n\t\tif(t==k)\n\t\t{\n\t\t\tif(sum<s)\n\t\t\t{\n\t\t\t\ts=sum;\n\t\t\t\tfor(j=0;j<k;j++)\n\t\t\t\t d[j]=o[j];\n\t\t\t}\n\t\t}\n\t\telse if(i<=m && t<k)\n\t\t{\n\t\t\tfloat ww[55];\n\t\t\tfor(j=1;j<=n;j++)\n\t\t\tww[j]=w[j];\n\t\t\tdfs(t,i+1,o,w,sum);\n\n\t\t\tf1=0,f2=0;\n\t\t\tif(f[i]==0)\n\t\t\t{\n\t\t\t\to[t]=i;\n\t\t\t\tif(t>0)\n\t\t\t\t{\n\t\t\t\t\tf2=1;\n\t\t\t\t\tfor(j=1;j<=n;j++)\n\t\t\t\t\t{\n\t\t\t\t\t\tif(ww[j]>yc[i][j])\n\t\t\t\t\t\t{\n\t\t\t\t\t\t\tsum=sum-ww[j]+yc[i][j];\n\t\t\t\t\t\t\tww[j]=yc[i][j];\n\t\t\t\t\t\t\tf1=0;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\telse\n\t\t\t\t{\n\t\t\t\t\tfor(j=1;j<=n;j++)\n\t\t\t\t\t{\n\t\t\t\t\t\tsum+=yc[i][j];\n\t\t\t\t\t\tww[j]=w[j]=yc[i][j];\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tif(f1 && f2)\n\t\t\t\t{\n\t\t\t\t\tf[i]=1;\n\t\t\t\t\tdfs(t,i+1,o,w,sum);\n\t\t\t\t}\n\t\t\t\telse\n\t\t\t\t{\n\t\t\t\t\tdfs(t+1,i+1,o,ww,sum);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n}\nint main()\n{\n    int i,j,o[12];\n    float w[55];\n    cin>>n>>m>>k;\n    for(i=1;i<=n;i++)\n    cin>>c[i][0]>>c[i][1];\n    for(i=1;i<=m;i++)\n    {\n        cin>>y[i][0]>>y[i][1];\n        for(j=1;j<=n;j++)\n        yc[i][j]=sqrt((c[j][0]-y[i][0])*(c[j][0]-y[i][0])+(c[j][1]-y[i][1])*(c[j][1]-y[i][1]));\n    }\n    dfs(0,1,o,w,0);\n    for(i=0;i<k;i++)\n    cout<<d[i]<<\" \";\n    return 0;\n}\n\n E 正文"}]};